quests[12134] = { id = 12134, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sasha's Hunt", description = "This thing... this curse... that's affecting Silverbrook and Solstice Village... it makes beasts out of people.\n\nMy father tried to warn them, but they all listened to the wolfcult instead.\n\nThey're too far gone now, it's time to put them down... for their own sake.", sourceObjective = "Sasha wants you to kill 12 Solstice Hunters in Solstice Village.", progress = "Have you taken care of the hunters in the village yet, {name}?", completion = "Killing these monsters won't bring my father back... but that's not the point now, is it?", sourceObjectiveStatus = "unverified-source-field" }
quests[12135] = { id = 12135, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Let the Fires Come!\"", description = "You must help us!  The Headless Horseman will attack the village at any moment!  Fires will be everywhere!  The children aren't safe!\n\nPlease, {name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", sourceObjective = "The Costumed Orphan Matron wants you to help put out all the village fires after the Headless Horseman lights them. When they are out, speak again to the Costumed Orphan Matron.", progress = "{name}, you promised to save the children!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.", sourceObjectiveStatus = "unverified-source-field" }
quests[12136] = { id = 12136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Translated Tome", description = "Here it is, {name}. I have translated everything printed upon the pages of the tome. Inside it you will find a list of the names of Cult of the Damned members spanning the entire continent.\n\nTheir network of spies and operatives is impressive, to say the least.\n\nFarewell, friend. May the book serve you and your people well.", sourceObjective = "Deliver the Translated Flesh-bound Tome to Captain Gort at Agmar's Hammer.", progress = "It's about time! Where have you been?", completion = "<Gort takes the tome from you and begins reading.>\n\nWHAT! This can't be right. I've known some of these orcs for years!\n\nLeave me, {name}. I have much work to do and many traitors to execute.\n\nTake one of these items for your trouble. You've done a great service for the Horde this day.", sourceObjectiveStatus = "unverified-source-field" }
quests[12137] = { id = 12137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chill Out, Mon", description = "It be as the prophecies said, mon. A {race} {class} be comin' to set our spirits to rest. We been waitin' for a long time now!\n\nThe Drakkari have become a lost people, fierce and savage.\n\nBut here we suffer by no fault of our own, mon. This place need cleansin' and only the living can do it.\n\nSpeak to me when ya be ready to rejoin your body. Then take the snow from the chest near me here and put my bruddas to sleep.\n\nTake their remnants to your spirit guide. He be knowin' what to do next.", sourceObjective = "Gan'jo wants you to collect the Snow of Eternal Slumber from his chest in the Drakil'jin Ruins.\n\nYou are to use the Snow on the Ancient Drakkari Spirits there and take their Drakkari Spirit Particles back to Kraz at Harkor's Camp.", progress = "Have you completed your task in the crypt, {class}?", completion = "You have done well.\n\nPlease, sit and listen. There are many things we must discuss.", sourceObjectiveStatus = "unverified-source-field" }
quests[12138] = { id = 12138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Or Maybe We Don't", description = "You'd think the guys making the power cells would've thought to power them up, but no, they've got to make it difficult for us.\n\nFine, we'll charge those cells the hard way. There's enough power in them to run the golem for a short time, but don't expect it to be any good in combat.\n\nYou see the lightning sentries that the irons have posted around the perimeter of Dun Argol? Bring the golem with you, take it close to them, and use the golem to absorb the power as the sentries die.", sourceObjective = "Charge your War Golem with the energy from 10 Lightning Sentries and return to Raegar Breakbrow at Prospector's Point.", completion = "Finally, it's ready. I only hope it holds together long enough to get the job done. If we don't take out the thane leading Dun Argol, Captain Gryan'll be in for a nasty surprise.", sourceObjectiveStatus = "unverified-source-field" }
quests[12139] = { id = 12139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Let the Fires Come!\"", description = "The Headless Horseman will attack the village at any moment!  Fires will be everywhere!\n\n{name}, will you face the fires of the Headless Horseman?  When he comes, you must join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  If you put out all the fires then we may yet be saved!", sourceObjective = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", progress = "The Horde's children need you!  Do not abandon them!", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today.", sourceObjectiveStatus = "unverified-source-field" }
quests[12140] = { id = 12140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Hail Roanauk!", description = "Like the tauren, Forsaken, trolls and blood elves, so too do the taunka need a leader born of their own blood. The one you saved from Icemist, Roanauk, will be this leader.\n\n<Overlord Agmar hands you a parchment.>\n\nI give to you something familiar - the blood oath of the Horde.\n\nTake the oath to Roanauk Icemist and initiate him into the Horde as leader of the taunka.\n\nLet us not keep him waiting.\n\n<Agmar nods.>", sourceObjective = "Seek out Roanauk Icemist at Agmar's Hammer and initiate him as a member and leader of the Horde forces.\n\nReturn to Overlord Agmar with the Blood Oath of the Horde when you complete this task.", progress = "Do not waste time, {name}. Angrathar awaits!", completion = "With the aid of such a powerful shaman, we are sure to be victorious at the Wrathgate!", sourceObjectiveStatus = "unverified-source-field" }
quests[12141] = { id = 12141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Diplomatic Mission", description = "I see that you are very eager to help, {name}.  You didn't come all the way to Northrend to stay holed up in a city!  I've just the task for you... something that'll take you far away from here.\n\nWe've long sought to gain the favor of the tuskarr native to Northrend.  Recently a young tuskarr came to us seeking help, something we couldn't offer at the time.\n\nNow that you're around, maybe you can lend him a hand.  Look for Karuk near the Riplash Strand, southwest of here, and see what you can do to help.", sourceObjective = "Speak to Karuk at Riplash Strand, southwest of Valiance Keep.", completion = "You've come to my aid?  I thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12142] = { id = 12142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Control", description = "Ugh! One of those little snobold runts trashed our camp while we were busy with that last dragon. They've been plaguing us whenever we turn our backs... I've had enough!\n\nTo the south you'll find the snobolds hiding under the skirts of some of the local magnataur. Go slaughter them.\n\nIf the magnataur interfere on behalf of their slaves, kill them as well.", sourceObjective = "Duane at the 7th Legion Front wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.", progress = "Did you finish off those pests?", completion = "Good riddance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12143] = { id = 12143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canyon Chase", description = "I can't believe this! Another band of those vermin just tried to take off with more of our supplies. They're scurrying off towards that north canyon, get after them and deal with whoever they're going to!", sourceObjective = "Duane wants you to chase the snobolds down the canyon northeast of 7th Legion Front and deal with their leader.", completion = "Chilltusk, eh?  I've heard his name before.  That's some good work, {class}.  Hopefully we can turn our attention back to the dragon menace now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12144] = { id = 12144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pest Control", description = "Oi, mon! One of dose little snobold runts trashed our camp during da last dragon attack. Dey've been houndin us wheneva we turn our backs and I've had enough. \n\nTo da east you'll find da snobolds hiding under da skirts of some of da local magnataur. Go slaughter dem. If da magnataur interfere on behalf of deir slaves, kill dem as well.", sourceObjective = "Kontokanis at Dragon's Fall wants you to kill 10 Snowplain Snobolds and 3 Dragonblight Magnataur at the magnataur camps surrounding Wyrmrest.", progress = "Did ya finish off dose pests?", completion = "Good riddance, mon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12145] = { id = 12145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Canyon Chase", description = "I can't believe dis! Another band of dose vermin just tried ta take off with more of our supplies. Dey're scurrying down da canyon now, get after dem and deal with whoever dey're going to!", sourceObjective = "Kontokanis wants you to chase the snobolds down the canyon south of Dragon's Fall and deal with their leader.", completion = "Icefist, eh?  I've heard his name before.  Dat's some good work, mon.  Hopefully we Darkspear can turn our attention back to dat dragon menace now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12146] = { id = 12146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur.\n\nTake the horn south down the Path of the Titans to Wyrmrest and seek out someone who might be interested in these threatening implications.", sourceObjective = "Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.", progress = "Yes, {race}?", completion = "It is indeed strange for any magnataur to carry an item such as this... and very concerning. I am glad that you have shown this to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[12147] = { id = 12147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disturbing Implications", description = "The underside of the horn boasts an emblazoned seal with a hammer and a lightning bolt. Something about the horn seems extremely out of place on a Magnataur. \n\nTake the horn east across the Dragon Wastes to Wyrmrest and seek out someone who might be interested in these threatening implications.", sourceObjective = "Bring the Emblazoned Battle Horn to Wyrmrest and seek out someone who might be interested in assessing the potential threat.", progress = "Yes, {race}?", completion = "It is indeed strange for any magnataur to carry an item such as this... and very concerning. I am glad that you have shown this to me.", sourceObjectiveStatus = "unverified-source-field" }
quests[12148] = { id = 12148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of a Kind", description = "Such a strange seal to see among magnataur... it suggests an unusual amount of organization.\n\nMagnataur rarely put aside their aggressive natures to cooperate with each other.  I suspect they have their eyes set on raiding a large settlement.\n\nI very much doubt that this horn is unique, I need you to prove me wrong. In the canyon northwest of the Azure Dragonshrine you will find Bonesunder. Go challenge him and bring me back any evidence you find that might confirm my concerns.", sourceObjective = "Find and kill Bonesunder in or near the canyon northwest of the Azure Dragonshrine. Bring any evidence you find back to Aurastrasza at Wyrmrest Temple.", progress = "Did you find anything?", completion = "So it is true. They could not have chosen better timing for such an attack... between the Scourge and the blue flight, it is unlikely that anyone else has noticed yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12149] = { id = 12149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mighty Magnataur", description = "Magnataur are hideously violent creatures... this is the main reason we rarely see them come together in any real numbers without killing each other. A powerful leader has stepped up somewhere among them and we need to hunt him down if we are to stop this threat. \n\nI will start asking around. I need you to disrupt them as much as possible in the meantime.\n\nEast of here there are 3 torches erected. Near them, there are 3 dominant Magnataur - put them down to buy us some time to hunt down this leader.", sourceObjective = "Hunt down and kill Bloodfeast, Iceshatter, and Drakegore east of Wyrmrest Temple.\n\nBloodfeast resides in the southeastern corner of the Dragon Wastes, just north of the Emerald Dragonshrine. Iceshatter patrols the northern edge of the Mirror of Dawn. Drakegore wanders at the bottom of the cliffs west of the Bronze Dragonshrine.\n\nReturn to Aurastrasza at Wyrmrest Temple once the magnataur have been slain.", completion = "Excellent work. No one could tell me who this leader might be, but I was able to uncover the name of someone who will have our answer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12150] = { id = 12150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reclusive Runemaster", description = "Dregmar Runebrand is a magnataur runemaster... a rare breed. He's generally solitary, but has been known to associate with the more powerful and influential magnataur in Dragonblight for quite some time. He will know who this new leader is. \n\nIt is unlikely we will gain any aid with the increasing concerns with the Scourge and the blue flight, so I need you to procure the information from Dregmar by any means necessary.\n\nI was told he can be found amongst the cliffs overlooking the Mirror of the Dawn.", sourceObjective = "Locate Dregmar Runebrand near his cave on the path to the cliffs overlooking the Mirror of the Dawn. Challenge him and uncover the name of the magnataur leader by any means necessary. Return to Aurastrasza at Wyrmrest Temple once the information is obtained.", progress = "Did you get the name?  Do you know who the magnataur warlord is?", completion = "Grom'thar the Thunderbringer. Good. Let's end any threat these magnataur might pose here and now.", sourceObjectiveStatus = "unverified-source-field" }
quests[12151] = { id = 12151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanton Warlord", description = "There's no reason to suspect Dregmar's words are anything but true. Whether Grom'thar defeats you or is defeated by you, he can wash his hands of this.\n\nFollow his instructions... take the horn that you brought me earlier, travel to the ring of torches south of the Azure Dragonshrine, and blow it to announce your challenge.\n\nWhen Grom'thar the Thunderbringer arrives, kill him and bring me his head.", sourceObjective = "Travel to the ring of torches south of the Azure Dragonshrine and blow the Emblazoned Battle Horn. Defeat Grom'thar the Thunderbringer and bring his head back to Aurastrasza at Wyrmrest Temple.", progress = "Did you end this threat for good?", completion = "You are formidable indeed.\n\nWith Grom'thar the Thunderbringer gone, we can leave the remaining Magnataur to fight among themselves and turn our attentions back towards more prominent threats.\n\nImpressive work, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12152] = { id = 12152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jin'arrak's End", description = "It is good to see you back among the living. Many who travel the path of the dead do not return to speak of it.\n\nWhile you were away, a vision appeared to Kraz revealing what remains to be done.\n\nA sacred offering lies somewhere inside the crypt. Take this spirit dust fashioned from the remnants you collected and use it on the offering.\n\nThe infused offering will bring an end to the corrupted warlord and will release the many tormented souls.\n\nMay the spirits guide your actions, {name}.", sourceObjective = "Kraz at Harkor's Camp wants you to collect the Sacred Drakkari Offering from the Drakil'jin Ruins and use the Drakkari Spirit Dust on it. You must use the Infused Drakkari Offering at the gongs outside of Drakil'jin Ruins.", progress = "Has Jin'arrak been defeated, {name}?", completion = "It is done.\n\nYour selflessness has brought eternal peace to many souls, ending eons of misery.\n\nMay this act lighten your own soul and lessen your burdens, for I see that there are yet many perils you must face.\n\nFarewell, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12153] = { id = 12153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Iron Thane and His Anvil", description = "Now that you've charged up your war golem, we're going to put all that energy to good use. Activate the golem inside Dun Argol to take control of it.\n\nOur  information about Dun Argol's leader, Iron Thane Furyhammer, suggests his bodyguard protects him from all harm.\n\nThat bodyguard is the construct he travels with, called The Anvil. Disable the construct, and his protection will disappear.\n\nThe thane stays in the building at the top of Dun Argol and supervises production from the bottom level.", sourceObjective = "Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Raegar Breakbrow at Prospector's Point.", completion = "It worked?\n\n<Raegar clears his throat.>\n\nI mean... of course it worked! This is incredible!\n\nYears from now, Explorers' League initiates will hear the story of how Raegar Breakbrow, {name}, and some hunk o' junk golem defeated the thane of Dun Argol!", sourceObjectiveStatus = "unverified-source-field" }
quests[12154] = { id = 12154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackout", description = "The large hall at the top of Dun Argol houses the power source for the entire area. If you can destroy the power core, it will cripple Dun Argol for some time.\n\nNo power means no golems, no sentries, and no more lightning armaments.\n\nWhen we were sent up here, they told us these explosives were for excavation, but thanks to Iron Thane Furyhammer, the research has been scrapped. We may as well get some use out of them, though. They're the only thing we have on hand capable of destroying the power core.", sourceObjective = "Use Raegar's Explosives to destroy the Runic Power Core at Dun Argol, then report to Raegar Breakbrow at Prospector's Point.", completion = "<Raegar nods approvingly.>\n\nI can't stand to see explosives go to waste and it'll set our enemies back for sure.", sourceObjectiveStatus = "unverified-source-field" }
quests[12155] = { id = 12155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smash the Pumpkin", description = "This large jack-o'-lantern rests in the middle of the village.  It eyes those who look upon it, betraying a dark menace within.\n\nSmashing the pumpkin reveals an old, scorched holy symbol.", sourceObjective = "Give the Scorched Holy Symbol to the Masked Orphan Matron.", progress = "Yes, {name}?", completion = "You found this inside the Headless Horseman's jack-o-lantern?  It is an old symbol of the Light.  If must have been the Horseman's, before he was cursed and turned into the monster he is today.  Thank you, {name}.  This symbol deserves to be with paladins.  I will make sure they get it.\n\nOh, and I almost forgot!  You have a secret admirer...\n\nOne of the children wanted you to have this.  She was too shy to give it to you herself.", sourceObjectiveStatus = "unverified-source-field" }
quests[12156] = { id = 12156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "DEPRECAED", description = "I was meant to set off for Silverbrook, northwest of here, about an hour ago.  My military escort appears to be running late.\n\nI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.\n\nWe're negotiating a deal with the locals and timeliness is essential.  What do you say?  If you come with me, you'll be well compensated for your troubles.", sourceObjective = "Escort the Alliance Envoy to the town of Silverbrook. Report to Lieutenant Dumont at the Amberpine Lodge when you've completed this task.I was meant to set off for Silverbrook, northwest of here, about an hour ago. My military escort appears to be running late.\n\nI'll be damned if this diplomatic mission gets sidetracked because some new recruit overslept.\n\nWe're negotiating a deal with the locals and timeliness is essential. What do you say?  If you come with me, you'll be well compensated for your troubles.", sourceObjectiveStatus = "unverified-source-field" }
quests[12157] = { id = 12157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lost Courier", description = "We're lucky we made it this far, {name}.  We were ambushed by Scourge as soon as we landed.\n\nOne of our men turned out to be a spy for the Cult of the Damned.  Thassarian appears to have more evidence of cultist infiltration.  Apparently it goes all the way to the top.\n\nI've sent one of my best couriers to our outpost in western Dragonblight, but he has not yet returned. I fear he may have fallen to the Scourge. Will you go to Dragonblight and search for him? Courier Lanson is his name.", sourceObjective = "Speak to Courier Lanson at Stars' Rest in Dragonblight.", completion = "As I crossed the bridge into Dragonblight a small group of Anub'ar ambushed me! I was surrounded! Those monsters knew I was coming. I barely made it out of there with my flesh intact. This list I hold must be taken to Wintergarde Keep, but I am too badly injured to make the journey.", sourceObjectiveStatus = "unverified-source-field" }
quests[12158] = { id = 12158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollowstone Mine", description = "I've been meaning to send some of our lads to check out Hollowstone Mine.  Haven't had a chance to yet -- we've had our hands full between the Horde on the west and the iron dwarves to the east.\n\nIf Dumont sent you, though, the least I can do is point you in the right direction.\n\nYou'll find the mine entrance to the northwest, not far from here.  See if you think operations there can be salvaged.  We sure could use the additional resources until our mine in Farshire is operational again.", sourceObjective = "Look for clues inside Hollowstone Mine northwest of the Westfall Brigade Encampment.", completion = "You've come to help me, haven't you!", sourceObjectiveStatus = "unverified-source-field" }
quests[12159] = { id = 12159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Souls at Unrest", description = "<Petrov looks deeply disturbed, breathing heavily and shifting his gaze nervously around the mine.>\n\nMy comrades... we must put their souls to rest!  I kill them and kill them but.. they just come back!\n\nI've had an idea for a while but I just don't have the heart to do it myself.\n\nMaybe you can do this for me?  Take this lantern and use its oil to burn their remains so they never get up again.\n\nI'll answer your questions later.  Help my friends first!", sourceObjective = "Petrov at Hollowstone Mine wants you to use the Miner's Lantern to burn the corpses of 8 Hollowstone Miners.", progress = "Have you put my friends to rest yet, {name}?", completion = "Rest in peace friends!  Do not worry -- I will tell everyone that we never gave up!", sourceObjectiveStatus = "unverified-source-field" }
quests[12160] = { id = 12160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Name from the Past", description = "It worked!  It worked!  My comrades can finally enjoy their well-earned rest...\n\nI'll stay here and finish the job.  We Hollowstone miners always finish the job -- we never give up!\n\nThat's why Arugal made an example of us.  We wouldn't fall in line, you see?  We wouldn't join his wolfcult!", sourceObjective = "Return to Captain Gryan Stoutmantle at the Westfall Brigade Encampment.", completion = "Curse our luck.  We find the one functioning mine this side of the hills and it's full of Scourge.\n\nNo offense, friend.  But that survivor you found sounds like he's been a little traumatized due to losing his friends.  Arugal's been dead for years... I even saw his grave once.", sourceObjectiveStatus = "unverified-source-field" }
quests[12161] = { id = 12161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna the Blind", description = "Hey there.  I overheard what you were saying to the captain and I just want you to know...  things aren't that simple in Northrend.\n\nJust because someone's dead it doesn't mean they're out of the picture.\n\nSouthwest of here, near Vordrassil Pass, lives a blind woman who goes by the name Ruuna the Blind.  They say she speaks to the dead and has visions of the past and future.\n\nI haven't heard your whole story but it sounds like she'd be right up your alley.", sourceObjective = "Speak to Ruuna the Blind at Ruuna's Camp near Vordrassil Pass.", completion = "You seek knowledge beyond your reach so you've come to me.  I must warn you, stranger, the answers I provide might not be to your liking.", sourceObjectiveStatus = "unverified-source-field" }
quests[12162] = { id = 12162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solstice Village" }
quests[12163] = { id = 12163, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Evil Below" }
quests[12164] = { id = 12164, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hour of the Worg", description = "It is time, then, {name}.  Arugal must be defeated.\n\nGet a couple of people you can trust and head for Bloodmoon Isle.  It's just off the coast, east of here.\n\nWe'll hit them fast.  Take out Arugal's lieutenants -- I'll catch up with you when it's time to take out the monster himself.", sourceObjective = "Sasha at the White Pine Trading Post wants you to go to  Bloodmoon Isle and slay Selas, Varlam, Goremaw and the Shade of Arugal.", progress = "It's good to see you, {name}.", completion = "We got him good, {name}.  But not good enough.\n\nOne thing's for sure... we won't be seeing him around these parts any longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12165] = { id = 12165, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Intriguing Plan", description = "Prospector Rokar has decided to help us. He's concocted a plan to use the iron dwarves' strength against them.\n\nI must admit, our new 'friend' is more insightful than I'd given him credit for. He's correct in that our numbers are too few for a direct attack.\n\nTravel to Dun Argol, in the snowy regions to the southeast, and capture all the parts of their war golem blueprints from the iron rune-smiths there. Bring the assembled blueprint to Rokar and we'll see if his plan has any merit.", sourceObjective = "Bring the completed War Golem Blueprints to Prospector Rokar at Camp Oneqwah.", progress = "Do... do you have those blueprints I asked for?", completion = "So Tormak's going to go ahead with the plan? I suppose he wouldn't have sent you if he didn't.\n\nOh, bother... Now how am I going to figure out how to put this together under all this pressure?", sourceObjectiveStatus = "unverified-source-field" }
quests[12166] = { id = 12166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Liquid Fire of Elune", description = "{race} will you assist me?\n\nThe Scourge have moved into Icemist to the north. Wherever they go, they spread their taint, and the creatures of the land suffer.\n\nTake this vial, which is filled with the liquid fire of Elune from the moonwell. Please, use the liquid to cleanse the corpses of the blighted wildlife that you find.", sourceObjective = "Warden Jodi Moonsong at Stars' Rest has asked you to use the Liquid Fire of Elune to cleanse the corpses of 6 Blighted Elk and 6 Rabid Grizzlies.", completion = "We have done what we can for the creatures of the land. Now we must take direct action against those that have caused this!", sourceObjectiveStatus = "unverified-source-field" }
quests[12167] = { id = 12167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill the Cultists", description = "The Anub'ar cultists are indirectly responsible for the plaguing of the beasts, and we must put an end to it!\n\nThe fumes that emit from the cultists' suits seep into everything they come near, poisoning and corrupting their surroundings.\n\nYou must go north to Icemist Village and slay them. Bring back any of their suits that survive your assault and I will see to it that they are properly disposed of.", sourceObjective = "Collect 5 Functional Cultist Suits for Warden Jodi Moonsong at Stars' Rest.", progress = "The cultists are a blight upon creation!", completion = "Well done.\n\nI will dispose of these filthy garments by cleansing them in the moonwell and destroying them through the power of the goddess!", sourceObjectiveStatus = "unverified-source-field" }
quests[12168] = { id = 12168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Favor of Zangus", description = "An inscription on the back of the favor reads,\n\n\"To my favorite pupil,\n\nIf you continue to show promise, I will teach you wonders beyond your imaginings.\n\nIf you do not, I will have you destroyed!\n\nAs ever,\n\nHigh Cultist Zangus\"\n\nNo doubt the warden at Stars' Rest will want to see this.", sourceObjective = "Deliver the Favor of Zangus to Warden Jodi Moonsong at Stars' Rest.", progress = "I sense something foul is near.\n\nIt is upon your person! What is it, {name}?", completion = "So, the leader of the cultists has revealed himself. We have a name.\n\nVanity and pride will be his downfall!", sourceObjectiveStatus = "unverified-source-field" }
quests[12169] = { id = 12169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Cultist", description = "I have dreamed of Zangus before but without the context that you have discovered, I knew not what it meant. You have brought clarity to the vision that the goddess has bestowed upon me, and now I know that he can be found within the Pit of Narjun to the north.\n\nYou know your target, {name}. If there's to be an end to the suffering of the land, the high cultist must die!", sourceObjective = "Warden Jodi Moonsong at Stars' Rest has asked you to slay High Cultist Zangus.", progress = "I sense that High Cultist Zangus yet lives.\n\nIs there something wrong, {name}? Perhaps you need to rest first?", completion = "With the high cultist destroyed, the rest of his forces can be mopped up and the land and its creatures will recover.\n\nThank you, {name}. May the goddess illuminate your path.", sourceObjectiveStatus = "unverified-source-field" }
quests[12170] = { id = 12170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackriver Brawl", description = "The Venture Company abandoned operations shortly after we showed up.  Clearly they were afraid of what we were going to do to their greedy little hides.\n\nWith them gone, their logging camps are up for grabs.  Our war machine is a hungry beast... without renewing our supplies we won't make it to Icecrown.\n\nUnfortunately the Alliance seems to have the same idea and we must make sure we're the ones that prevail.  Head into the logging camp and help us fight the Alliance scum.", sourceObjective = "Raider Captain Kronn wants you to slay 10 Alliance units or players at the Blackriver Logging Camp.", progress = "Have you slain the Alliance dogs?  Victory must be ours!", completion = "Well done, {name}.  Our control over the logging camp might not be complete yet, but thanks to you we're one step closer to smashing these Alliance worms.", sourceObjectiveStatus = "unverified-source-field" }
quests[12171] = { id = 12171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Palena Silvercloud here at Stars' Rest and explain the nature of your mission. She will put you on her fastest hippogryph to Wintergarde!", sourceObjective = "Show the Alliance Missive to Palena Silvercloud at Stars' Rest.", progress = "Hello, {race}.", completion = "<Palena reads the note.>\n\nYou will take my fastest hippogryph, {race}! This information must be delivered to High Commander Wyrmbane at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[12172] = { id = 12172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attunement to Dalaran", description = "Welcome, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I will help you.\n\nBut before I can teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you risk destroying yourself in the process.\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the west. Then you will be ready to learn the spell.", sourceObjective = "The Image of Archmage Modera at Stars' Rest has asked you to become Attuned to the Ley Lines of Northrend.", progress = "Are you attuned? You mustn't lie about this, {name}.\n\nIf you fail to prepare yourself properly, and I teach you the spell, the first time that you cast it will be the last time anyone will ever see you!", completion = "Very well. If you are ready, then so am I.", sourceObjectiveStatus = "unverified-source-field" }
quests[12173] = { id = 12173, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attunement to Dalaran", description = "Hello, mage.\n\nBy now you must be wondering where Dalaran is and how to get there. I can help you with this if you can survive a simple test.\n\nBefore I teach you how to teleport to our great city, you must attune yourself to the ley lines of Northrend. Otherwise, you will destroy yourself in the process!\n\nTake this attunement crystal and use it in the pit under the surge needle at the Moonrest Gardens to the southwest. Then you will be ready to learn what I have to teach.", sourceObjective = "The Image of Archmage Aethas Sunreaver at Agmar's Hammer has asked you to become Attuned to the Ley Lines of Northrend.", completion = "Very well. If you think you are ready, then let's not waste anymore of my time.", sourceObjectiveStatus = "unverified-source-field" }
quests[12174] = { id = 12174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Commander Halford Wyrmbane", description = "<Palena hands the missive back to you.>\n\nSnowstorm will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!", sourceObjective = "Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.", progress = "What have you got there, soldier?", completion = "<The High Commander reads the missive and then crumples it up.>\n\nDo you know where the people on this list are now? Take a look outside, near the front gate. They're the ones hanging from the arches.\n\nGhoul bait...", sourceObjectiveStatus = "unverified-source-field" }
quests[12175] = { id = 12175, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gray Worg Hides", description = "Let me tell you something, mon.  When you get put in charge of outfittin' the armies of the Horde, you go through a lot of hides!\n\nConqueror Krenna, the she-wolf runnin' this place, she gave me a tight deadline.  If I don't outfit her whole regiment by week's end she's gonna have me wrestling bears in the pit.\n\nHelp me out and I'll pay you top price.  I'll be needin' hides from graymist hunters.\n\nYou'll find them all around in pockets to the north, hunting stag.  Remember, mon.  Top price!", sourceObjective = "Hidetrader Jun'ik in Conquest Hold wants you to get 3 Gray Worg Hides from Graymist Hunters in the woods to the north.", progress = "You get dose hides, mon?", completion = "You're a life saver, brother.  If you're interested in more work, there's more where that came from.", sourceObjectiveStatus = "unverified-source-field" }
quests[12176] = { id = 12176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Minor Substitution", description = "Krenna, she be wantin' worg hides for all the outfits.  There's not gonna be enough worg hides for her army, though.  Not now, not ever.\n\nThose worgs -- they be skinny, mon!  Here's what we're gonna do... if you can keep a secret that is.\n\nEast of Voldrune there be grizzly bears as fat as an ogre.  Those large hides -- those we can use!\n\nHurry, <brother/sister>.  Krenna's not known for her patience.", sourceObjective = "Hidetrader Jun'ik wants you to bring him 6 Grizzly Hides.", progress = "You get those hides, mon?", completion = "I'm in your debt, mon.  Take this as payment.", sourceObjectiveStatus = "unverified-source-field" }
quests[12177] = { id = 12177, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jun'ik's Coverup", description = "Ah, we have a small problem.  Grizzly hides... they be brown, mon!\n\nThink... think!\n\nI got it, mon!  Is like this: gray is black an' white all mixed up.  You get me some coal an' some flour, I'll grind it all up and dust the hides with it.  No one will know the better!\n\nBlacksmiths sell coal for smeltin' an' you can get flour from the provisioner.", sourceObjective = "Bring 1 piece of Coal and 5 Simple Flour to Hidetrader Jun'ik at Conquest Hold in Grizzly Hills.", progress = "You get the stuff, mon?", completion = "Hope for the best, mon.", sourceObjectiveStatus = "unverified-source-field" }
quests[12178] = { id = 12178, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delivery to Krenna", description = "This is it, mon.  Let's take these hides to Krenna and see if they pass the test.\n\nLet's hope for both our sakes Krenna doesn't notice anything.", sourceObjective = "Take the Bundle of Hides to Krenna in Conquest Hold.", progress = "Do you have any idea who you're talking to?", completion = "Just who do you take me for?  These hides smell of flour!\n\nThis is a complete insult to the Horde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12180] = { id = 12180, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Captive Prospectors", description = "Raegar sent a team of prospectors into Dun Argol to search for artifacts and information about the history of the settlement. Raegar's team never expected Dun Argol to be this heavily populated.\n\nThey're being held captive while the iron dwarves prepare for war. We haven't the men to charge in after them, and Raegar's too busy fantasizing about defeating the irons to be of much help.\n\nIt falls to you, {name}. Any of the irons or their servants could be carrying the keys to the cages holding our men.", sourceObjective = "Free Prospector Gann, Prospector Torgan, and Prospector Varana, then return to Mountaineer Kilian at Prospector's Point.", progress = "Did you locate the missing prospectors?", completion = "<Mountaineer Kilian listens as you relate what the captive prospectors told you.>\n\nThey mentioned Loken and a war against stone giants? You're certain?\n\nSo Raegar's instincts were right. We have to find a way to get in there and learn more about their plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[12181] = { id = 12181, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Give it a Name", description = "My, my, how long has it been? How long have we been working on this damned plague? Finally, after an eternity of failure, we are blessed with perfection. This... It doesn't even have a proper name yet! This blight... That's it, BLIGHT! This blight will tear down the very fabric of life!\n\n<Harris hands you a vial.>\n\nNow, find the bat handler, Tobias, and show him the specimen. He'll get you on your way to Venomspite.", sourceObjective = "Show the Blight Specimen to Tobias Sarkhoff at New Agamand.", progress = "Highly lethal poisonous gas delivery to Venomspite? Step right up!", completion = "Uh, yea, you can go ahead and hold on to that vial, friend. I trust you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12182] = { id = 12182, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To Venomspite!", description = "I got a special bat all lined up for you, buddy. Fastest and smoothest ride I've got. He'll take you right to Venomspite - in style.\n\nJust hand that vial over to Chief Plaguebringer Middleton once you land.", sourceObjective = "Deliver the Blight Specimen to Chief Plaguebringer Middleton at Venomspite in eastern Dragonblight.", progress = "You are the delivery boy?", completion = "Oh joyous day! And look, just beyond the mountain to the northeast creeps a whole field of Scourge for us to obliterate!", sourceObjectiveStatus = "unverified-source-field" }
quests[12183] = { id = 12183, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Looking the Part", description = "If, as Prospector Varana said, only certain irons are permitted to communicate with this Loken, it'll probably be the overseers who have the privilege.\n\nWe have to get you in there to see what all this is about, but it won't be easy. The first step will be to get a proper uniform for you.\n\nThen, we'll worry about doing your makeup.\n\nFind one of the overseers at Dun Argol, kill him, and bring back his uniform. If you get blood on it, you'll have only yourself to blame.", sourceObjective = "Bring an Overseer's Uniform to Mountaineer Kilian at Prospector's Point.", progress = "Did you get the uniform?", completion = "<Kilian takes the uniform from you.>\n\nThis should do. I won't have time to sew on a little patch with '{name}' embroidered on it or anything, but anyone looking closely at you should be convinced that you're an overseer by the time we're done with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12184] = { id = 12184, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultivating an Image", description = "Now that we've got the uniform, we've got to get enough information to complete your camouflage.\n\nRaegar brought along this camera to document the team's finds, but I have a different use in mind. I want you to take it with you to Dun Argol and use it to capture the images of iron dwarves.\n\nOf course, your models aren't going to be a cooperative lot, so you may have to, err... subdue them first. Bring back the camera and the images when you're done.", sourceObjective = "Use Kilian's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Mountaineer Kilian at Prospector's Point.", progress = "Did you get those snapshots?", completion = "Good, these should do. Now, to create a kit to pass you off as a convincing iron dwarf.", sourceObjectiveStatus = "unverified-source-field" }
quests[12185] = { id = 12185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put on Your Best Face for Loken", description = "Using the images you've captured, I've created everything you need for your overseer disguise kit. You'll make a fine iron dwarf, if I do say so myself.\n\nTake the kit with you to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", sourceObjective = "Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Mountaineer Kilian at Prospector's Point.", progress = "Did the disguise work?", completion = "Could it be that Loken isn't really exaggerating? The titans' stone and iron sons fighting against each other for control of the ancient city of Ulduar. This is madness, {name} and it could destroy our only chance to learn the true history of dwarvenkind!", sourceObjectiveStatus = "unverified-source-field" }
quests[12188] = { id = 12188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken Blight and You: How Not to Die", description = "The details behind the functionality of the blight are hardly important. All you need to know is that it does the job it was designed to do. I have managed to synthesize a strain of the blight that is inert.\n\n<Middleton uncorks a vial and inhales.>\n\nSee, my body is still, mostly, intact. Now mix this with a reactive agent and we'd all be turned to shapeless piles of goo.\n\nOn the beach south of here you will find pathetic specters of Alliance soldiers past. Slay them and bring me ectoplasmic residue.", sourceObjective = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to bring him 10 Ectoplasmic Residue.", progress = "The residue will be used as the reactive agent to activate the blight!", completion = "This will do nicely, {name}. Did those pathetic whelps put up a fight or did they just shower you with ghostly tears of sorrow?\n\nAh, they get so emotional...", sourceObjectiveStatus = "unverified-source-field" }
quests[12189] = { id = 12189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imbeciles Abound!", description = "The shipment from New Agamand was to arrive at Venomspite last week and then be delivered to me after some simple field tests. It is a Horde imperative - the last piece of the \"victory puzzle.\"\n\n<Sintar sighs.>\n\nIt is quite disheartening to know that you are surrounded by imbeciles and incompetent boobs!\n\nYou must travel to Venomspite, near the eastern border of Dragonblight. Find that buffoon, Middleton, and let him know that I am waiting on the package.", sourceObjective = "Travel to Venomspite in Dragonblight and speak with Chief Plaguebringer Middleton.", completion = "We ran into a little - MINOR - problem. Everyone that tried handling the blight vaporized. We're working on adjusting the formula a tad so it doesn't instantly kill you for looking at it sideways. The good news is that I think I've almost got it!", sourceObjectiveStatus = "unverified-source-field" }
quests[12190] = { id = 12190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say Hello to My Little Friend", description = "Harkor's gunna drop a gold brick when he sees these choice ingredients. All that be left is gettin' them to him.\n\nHe's camped out on the eastern coast near dem haunted ruins - Drakil'jin, dey be called.\n\nYou'll likely be makin' it there before I can finish up with these corpses... unless, ya think you'd rather try your hand at embalming?", sourceObjective = "Prigmon wants you to bring Harkor's Ingredients to Harkor at Harkor's Camp.", progress = "What can I do fer ya?", completion = "Well now! Good ol' Prigmon sent ya did he?\n\nThis should make fer some mighty fine eatin'. Needs just a couple things...", sourceObjectiveStatus = "unverified-source-field" }
quests[12191] = { id = 12191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chug and Chuck!", description = "Those pesky Dark Irons are back! We need to make sure that you can defend yourself if needed. More importantly, we need to know that you can defend our property!\n\nS.T.O.U.T. here is ready for action, are you? Drink from the Alcohol-Free Brewfest Samplers then throw the mug at S.T.O.U.T.! Hit the target 5 times then talk to me.", sourceObjective = "Use the Alcohol-Free Brewfest Sampler to hit S.T.O.U.T. 5 times, then talk to Bizzle Quicklift.", progress = "Chug from the mug, then chuck the mug at S.T.O.U.T.  I think he can withstand the pounding.  I wouldn't have stol.. er... built him if he couldn't!", completion = "Wow...  S.T.O.U.T. didn't break... Hmm... Who would have guessed?\n\nI mean, hey, you did it!  Your aim is true, or at least true enough to help guard the camp.  I think you're ready now to take on the Dark Irons if they show up again.", sourceObjectiveStatus = "unverified-source-field" }
quests[12192] = { id = 12192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Time, When I Was Drunk...", description = "The Dark Irons took a beating!  As they rushed back to the Grim Guzzler, a portion of their transport fell off.  More importantly, you managed to keep the camp safe... today.\n\nHead over to Bizzle and explain your heroic triumph over the Dark Iron dwarves.", sourceObjective = "Talk to Bizzle Quicklift in the Brewfest camp.", completion = "So you managed to stop the Dark Irons... While drunk too?  That, {class}, is truly the spirit of Brewfest!  I guess in keeping with the spirit of Brewfest you want your prize tokens.\n\nThanks for your help, {name}.  Enjoy the rest of Brewfest.", sourceObjectiveStatus = "unverified-source-field" }
quests[12193] = { id = 12193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.", sourceObjective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "Aww, it's just a stein voucher... Maybe you're just playing hard to get.  So here's this year's stein for you.\n\nBut I suspect I'll be seeing a lot more of you.  After all, if you want any Brewfest tokens redeemed, I'm your girl...\n\nOr maybe I'm his girl...  \n\nOooohhh... or his...", sourceObjectiveStatus = "unverified-source-field" }
quests[12194] = { id = 12194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Say, There Wouldn't Happen to be a Souvenir This Year, Would There?", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.", sourceObjective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", progress = "What's happening hot stuff?  Got something for me?", completion = "What's this?  A stein voucher?  So you like drinking?  Great!  After I give you this stein, go have a few drinks!  Then a few more.  Maybe have a few more after that...  Then, now this is important, come see me.\n\nLook, I know you'll be back eventually.  If you want your Brewfest tokens redeemed you have to see me.\n\nAnyways, here's the stein, and remember to talk to me later.", sourceObjectiveStatus = "unverified-source-field" }
quests[12195] = { id = 12195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Unexpected 'Guest'", description = "A recent hunting expedition brought back more than just game.\n\nThey encountered a wounded dwarf fleeing the iron dwarf stronghold of Dun Argol. He may have information we can use to strike at our ancient enemy, but before he's of any use to us, we must bring down his fever.\n\nThe horns of the silvercoat stags, who roam the nearby forest, have long been used to make healing poultices. If you can bring enough of the horns to me, we'll see if the poultice can bring our 'guest' around.", sourceObjective = "Bring 5 Mature Stag Horns to Tormak the Scarred at Camp Oneqwah.", progress = "Did you bring the horns?", completion = "These should serve. Now, let's see if it works.", sourceObjectiveStatus = "unverified-source-field" }
quests[12196] = { id = 12196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "From the Ground Up", description = "We don't have enough time for me to forge the parts myself, but the foundries over at Dun Argol, to the southeast, are working day and night to churn out golem parts.\n\nI think you should go back there and pick up enough of them for me to make a golem from this blueprint.\n\nThey're probably scattered around any of the buildings where the iron rune-smiths are working.\n\nPlease hurry, {name}. That Tormak looks like he's just waiting for an excuse to carry out his threat!", sourceObjective = "Bring 8 War Golem Parts to Prospector Rokar at Camp Oneqwah.", progress = "D-did you b-b-bring those golem parts?", completion = "<Rokar wipes his forehead with the back of his hand.>\n\nOh, thank the Light. He was threatening not to feed me until you returned. Let's sort through this pile of parts and see what we can make.", sourceObjectiveStatus = "unverified-source-field" }
quests[12197] = { id = 12197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have the Power", description = "Well, we've got the shell of a golem, but that's not good enough for Tormak. He doesn't realize that these things don't just come together and miraculously start working! We're going to need power cells to animate it.\n\nWhen I was in Dun Argol, I noticed that Rune-Smith Durar and Rune-Smith Kathorn were the ones who manufactured the cells. We'll need one from each to power our golem.\n\nYou should be able to find each rune-smith in his workshop on the central level of Dun Argol.", sourceObjective = "Bring Durar's Power Cell and Kathorn's Power Cell to Prospector Rokar at Camp Oneqwah.", progress = "Do you have those power cells?", completion = "<Rokar takes the batteries from you.>\n\nThese are low, but they'll be enough to start up the golem. He's nowhere near ready for battle, though.", sourceObjectiveStatus = "unverified-source-field" }
quests[12198] = { id = 12198, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "... Or Maybe We Don't", description = "The golem's cells have just enough power to run it at the lowest levels, but it can't power any of its combat systems.\n\nThe good news is that the perimeter of Dun Argol is patrolled by lightning sentries. We should be able to use their power to charge up the golem's weapon systems.\n\nBring the golem with you, take it close to them, it will absorb the power as the sentries die.", sourceObjective = "Charge your War Golem with the energy from 10 Lightning Sentries and return to Prospector Rokar at Camp Oneqwah.", progress = "Did you get that golem charged? Tormak is getting impatient again...", completion = "Well, now Tormak can't complain anymore. This baby's as ready as I can make it.\n\nAfter you tear your way through Dun Argol with it, that overgrown cow'll have to release me.", sourceObjectiveStatus = "unverified-source-field" }
quests[12199] = { id = 12199, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringing Down the Iron Thane", description = "Now that the golem is fully charged, it can be used against the leader at Dun Argol.\n\nWhen I observed Iron Thane Furyhammer, he was always guarded by a personal golem that shielded him from all harm.\n\nThat construct, called The Anvil, can be disrupted, causing him to drop the shield. Use your golem's EMP ability to do just that. You'll be able to activate and take control of your golem inside Dun Argol.\n\nThe thane is in the main plant at the top and supervises production from the bottom level.", sourceObjective = "Using the abilities of your War Golem, defeat Iron Thane Furyhammer, then return to Tormak the Scarred at Camp Oneqwah.", progress = "Please tell me it worked...", completion = "So the prospector made good on his promises? Good. I was beginning to wonder if all of this scrounging for bits of metal and stealing building materials would amount to anything.\n\nIt's a shame he's of no further use to us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12200] = { id = 12200, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Dragon Tears", description = "With an inert specimen of the blight compound complete and the activating agent in hand there only remains a need for a suitable shell to house the components.\n\nSouthwest of here, on the shores of central Dragonblight, is where you will find the Emerald Dragonshrine. Within the shrine you will find the hardened remnants of a green dragon's tear drop. I don't know the whole story, but apparently they cry a lot right before they die. Go figure.\n\nGo to the Emerald Dragonshrine and gather tears.", sourceObjective = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to collect 8 Emerald Dragon Tears.", progress = "Fortunate it is that we have a location nearby holding a surplus of emerald dragon tears. I would have had to send you to Feralas otherwise.", completion = "I do believe that the blight is now ready for a field test. Fortuitously, the dread citadel, Naxxramas, is laying siege to Wintergarde Keep. From beneath the very earth that Wintergarde was built upon rise the living dead, eager to do the bidding of Kel'Thuzad.\n\nThe Alliance are, of course, outmanned and outgunned. The people laid to rest in the Wintergarde Mausoleum awaken, hungering for flesh!\n\nPerhaps we shall give them a taste of the blight, yes?", sourceObjectiveStatus = "unverified-source-field" }
quests[12201] = { id = 12201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Overseer's Shadow", description = "It sounds like this Loken is the mastermind behind the sudden preparations for war on the part of the iron dwarves.\n\nOnly the highest ranking irons are likely to have access to him, so we'll have to make you into an overseer to find out what's going on in there.\n\nI have a plan, for that, but we'll need some supplies.\n\nFind one of the iron rune overseers at Dun Argol, to the southeast, kill him, and bring back his uniform.", sourceObjective = "Bring an Overseer's Uniform to Scout Vor'takh at Camp Oneqwah.", progress = "Did you get the uniform?", completion = "This should work, but there's still the matter of the rest of your disguise. Even those dimwitted metal dwarves will recognize an impostor with a stolen suit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12202] = { id = 12202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cultivating an Image", description = "Now we have to finish the job of making you as repulsive as those iron dwarves.\n\nThe best way to do that is to base your disguise on the ugly mugs of real iron dwarves.\n\nWhen Tormak's hunting party discovered that wayward prospector, they took the camera he carried. Now, I suppose, we'll get the chance to use it.\n\nTake it with you to Dun Argol, kill some iron dwarves, and record their likenesses in this device. Bring it back once you have enough examples.", sourceObjective = "Use Rokar's Camera to record the images of 8 Iron Dwarves in Dun Argol, then return to Scout Vor'takh at Camp Oneqwah.", progress = "Did you get those snapshots?", completion = "These should serve. By Garrosh, these creatures are ugly.", sourceObjectiveStatus = "unverified-source-field" }
quests[12203] = { id = 12203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loken's Orders", description = "I've created everything else you'll need for your overseer disguise kit. Try not to retch when you put it on. I took pains to make it as true to reality as possible.\n\nTake the kit with you southeast to Dun Argol, use it to disguise yourself, then go to the easternmost building on the broad middle tier of the city.\n\nThere, you should see a pedestal where the thane and overseers receive their orders from this Loken. Activate it while disguised and learn all you can from the communication.", sourceObjective = "Disguise yourself as an Iron Rune Overseer, intercept the message from Loken, then report to Scout Vor'takh at Camp Oneqwah.", completion = "So he means to foment civil war between the factions of the titans' creation? Why does this titan city of Ulduar mean so much to him? I suppose this is what Kurun and his giants are hoping to prevent.\n\nWell, I doubt we're in a position to keep the giants from fighting each other, but we can find a way to use this to our advantage. I must inform our leaders at once.", sourceObjectiveStatus = "unverified-source-field" }
quests[12204] = { id = 12204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In the Name of Loken", description = "The iron dwarves stand as one of the fiercest and most coordinated foes in Northrend. Wherever we have traveled, they have battled us with the name of Loken on their lips.\n\nWe must learn who this Loken is and what he seeks. The locals may be of help.\n\nTo the northeast, at the Redwood Trading Post, a human named Hugh Glass peddles his wares. Further east, at the Ruins of Tethys, you'll find a stone giant named Gavrock. Ask them about this Loken. They've got to know something of use.", sourceObjective = "Speak with Hugh Glass and Gavrock about Loken, then report your findings to Scout Vor'takh at Camp Oneqwah.", progress = "What did you find?", completion = "So he is the mastermind behind the iron dwarves? We must find out what he has been ordering the iron dwarves of Dun Argol to do.", sourceObjectiveStatus = "unverified-source-field" }
quests[12205] = { id = 12205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wanted: The Scarlet Onslaught", description = "By order of High Executor Wroth all members of the illegal organization known as the Scarlet Onslaught are to be put to death immediately.\n\nNo quarter is to be offered, and those proceeding to action upon this decree should be aware that any who are captured by the humans will be left to die, or worse!\n\nIn the High Executor's words, \"Paint the snow red with their blood!\"", sourceObjective = "Kill 20 members of the Scarlet Onslaught and report to High Executor Wroth at Venomspite.", completion = "Very well done, {race}. I trust that you were cleverly vicious in your slaying?\n\nLet's see, how much I can offer you from the coffins... er, excuse me, coffers?", sourceObjectiveStatus = "unverified-source-field" }
quests[12206] = { id = 12206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blighted Last Rites", description = "Have you read the wanted poster? What is the high executor thinking?!\n\n<Vicky looks around and continues in hushed tones.>\n\nWe can't very well have those Scarlet Onslaught idiots being raised by their priests, or worse, rising as the Scourge, now can we?\n\nNo, I'm in total agreement with you, we have to do something about the corpses.\n\nI have just the thing. Take this blight that we just created and test it on the prisoner in the cage right here.\n\nNo muss, no fuss, no returning enemies.", sourceObjective = "Apothecary Vicky Levine at Venomspite has asked you to test the Flask of Blight upon the Scarlet Onslaught Prisoner.", progress = "Did you do it?\n\nHey, I forgot to tell you that you probably shouldn't let any of that stuff get on you! It's nasty, and you'll never get the stains out, let alone have a hell of a time healing the bubbled-away fleshy bits.", completion = "WHAT?! That's impossible! We've perfected the blight. It has a one-hundred percent lethality.\n\n<The apothecary wrings her hands, concern crossing her unliving visage. Clearly frustrated, she continues in an angry tone.>\n\nThis is just really odd. Hand me that flask, {class}. I'm not going to be known as the apothecary that ruined everything!", sourceObjectiveStatus = "unverified-source-field" }
quests[12207] = { id = 12207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Fall", description = "Long ago, powerful druids planted a tree to the northeast of here.\n\nIt was called Vordrassil and it was to be a world tree.  It is not known why, but after the tree was fully grown, the druids decided it needed to be destroyed.\n\nEver since we arrived here, the earth has spoken to me, {name}.  Its cries of pain come from the places where Vordrassil's remains fell on the ground.\n\nCorrupting ooze roams those places.  Bring me samples of it so we may begin to heal the land.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.", progress = "Have you obtained the samples, {name}?", completion = "This slime is foul with a darkness far more ancient than their worldly forms would indicate.  The land itself has a memory of this evil for as long as it has existed.\n\nWe must find out more, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12208] = { id = 12208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Troll Hunting", description = "Good for nothing wretches!\n\nThey could have had it easy. We extended our hand in peace. All they had to do was give us passage through Drak'Tharon and we'd have let them be.\n\nBut no, the prideful little ice trolls decided that they wanted it rough. Now they'll be destroyed and we'll pass through their precious keep to Zul'Drak anyway.\n\nWe've contracted a gang to deliver us captured trolls. Talk to Samir if you want in on the action. You can find him to the northwest of here, due south of Zeb'Halek.", sourceObjective = "Sergeant Thurkin told you to speak to Samir at Granite Springs.", completion = "Here to get in on the bounty action, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12209] = { id = 12209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Materiel Plunder", description = "Ah good, new meat. Do you wish to prove yourself, new meat?\n\nThe Scarlet Onslaught, the most zealous and racist of the Scarlet Crusade, are in our backyard to the south. If we're going to fight them, we'll need more armor and weapons than I can make in such a short time.\n\nWhy don't we take theirs?\n\nMore to the point, why don't YOU take theirs?", sourceObjective = "Quartermaster Bartlett at Venomspite has asked you to steal 8 Scarlet Onslaught Armor and 8 Scarlet Onslaught Weapons.", progress = "I'll take what armor and weapons you can steal for me, new meat.\n\nThough they'll be of inferior quality to what I can make here, it's better than nothing.", completion = "You do not smell so fresh now, new meat.\n\nVery well, all of this will do. By what name might I call you, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[12210] = { id = 12210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Troll Season!", description = "You, {race}! No sense standing around here when there's work to be done!\n\nDrak'Theron Keep is the most direct route to Zul'Drak. We MUST capture it to ensure safe passage for the Alliance. But until we get the numbers to make an assault, we'll have to content ourselves in thinning out the ice trolls and collecting intel.\n\nTo that end, we've conscripted a gang of thugs to capture and deliver live trolls for interrogation. Travel northwest and speak with Samir at Granite Springs. He'll direct you further.", sourceObjective = "Lieutenant Dumont at Amberpine Lodge wants you to speak to Samir at Granite Springs.", completion = "Here to get in on the bounty action, eh?", sourceObjectiveStatus = "unverified-source-field" }
quests[12211] = { id = 12211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Let Them Not Rise!", description = "I don't understand it. The blight should have worked!\n\nNo sense worrying about it now.\n\n<The apothecary seems relieved for some reason.>\n\nThough it doesn't work on the Onslaught for some strange reason, we still need to keep their priests from raising them.\n\nI have another idea, one that their corpses shouldn't have any protection from.\n\n{name}, take a container of my rats and unleash them upon any Onslaught corpses you come across at New Hearthglen. I starve the vermin, so they should be voracious!", sourceObjective = "Apothecary Vicky Levine at Venomspite has asked you to use her Container of Rats to pick clean the corpses of 15 Scarlet Onslaught members at New Hearthglen.", progress = "Well? Success I assume?\n\nDon't tell me that they have some kind of protection against being eaten by rats?!", completion = "Oh good! For a moment I thought I was going to have to test the rats out on someone to make sure that they weren't defective.\n\nProgress, finally!", sourceObjectiveStatus = "unverified-source-field" }
quests[12212] = { id = 12212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Replenishing the Storehouse", description = "G'day, {class}.\n\nThe good lieutenant here says that there's been a Horde raid on our storehouse that's left our food supply dangerously low.\n\nNo doubt we'll make those cretins pay, but first we need to focus our attention on restocking. My men are doing all they can, but we're going to need every able body to contribute if we're to avert a crisis.\n\nYou should have no trouble harvesting venison from the local stag in these parts. Happy hunting!", sourceObjective = "Master Woodsman Anderhol at Amberpine Lodge wants you to kill Tallhorn Stag and collect 8 Succulent Venison.", progress = "How goes the hunt, {race}?", completion = "These are some choice pieces of meat!", sourceObjectiveStatus = "unverified-source-field" }
quests[12213] = { id = 12213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Darkness Beneath", description = "Something... dark... happened to the tree Vordrassil.  After the druids decided to destroy it, its hollow remains grew roots deep into the ground.\n\nI want you to go to the three locations to the northeast where the tree's trunk shattered and go as far beneath the ground as you can.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  This might shed some light on what happened to Vordrassil and why it failed to become a world tree.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.", completion = "This orb... it has been tainted by... a purely evil force.\n\nWhatever else I might learn from studying this energy, one thing is certain.  I must destroy this orb as soon as possible.  Its corrupting force is just too strong.", sourceObjectiveStatus = "unverified-source-field" }
quests[12214] = { id = 12214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fresh Remounts", description = "Hello. I am Hansel. Pleased to meet you, <sir/ma'am>.\n\nThe high executor came to me and said, 'Hansel, I want you to get us new mounts.'\n\nWhere does he think dreadsteeds come from? The ground?\n\n<whispering> Actually, they do if you can find a horse graveyard.\n\nBut we don't have one of those, so what we need you to do is go south to New Hearthglen, kill the knights, take their riding crops, and steal their warhorses.\n\nRide the horse back to me here and hand over the reins, if you would.", sourceObjective = "Hansel Bauer at Venomspite has asked you to steal 3 Onslaught Warhorses and deliver them to him, handing over the reins when you do so.", progress = "I'm sure glad that you came around. I was afraid that I was going to have to go down there and rustle them up myself.", completion = "Ah, nothing makes me happier than a job well done.\n\nYou've done Venomspite a great service in acquiring these horses, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12215] = { id = 12215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Them or Us!", description = "As if we didn't have enough to concern ourselves with....\n\nWith the present food crisis, we find ourselves competing for food with the local worgs. The situation is becoming more dire, and I fear that if we don't address the issue immediately we'll soon find ourselves with nothing to hunt.\n\nScour the forest, {race}. Kill any graymist you find. Recent reports have sighted a concentration of them on the other side of the river west of here.", sourceObjective = "Anderhol at Amberpine Lodge wants you to find and kill 6 Graymist Hunters in Grizzly Hills.", completion = "Good work, {class}.\n\nThis should help ensure that the wildlife in these parts ends up where it should - roasting over our fires.", sourceObjectiveStatus = "unverified-source-field" }
quests[12216] = { id = 12216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take Their Rear!", description = "We've all been working hard and it's beginning to pay off, but we're still far from our goal. We need much more meat than we have and it's growing clear that the local stag population won't be enough by itself.\n\nI'm afraid we need you to turn your attention to more dangerous prey - the grizzlies that give this region its name. They're plentiful, and they're well fed from the abundant fish that swim in these streams.\n\nBe safe, {class}!", sourceObjective = "Anderhol at Amberpine Lodge wants you to collect 8 Grizzly Flanks from the Grizzly Bears in Grizzly Hills.", progress = "The mighty {class} has returned!", completion = "Outstanding!\n\nOur stores are nearly replenished now. You've done your part, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12217] = { id = 12217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eagle Eyes", description = "Well, {name}, we've determined how the Horde was able to locate our hidden stores of food.\n\nIt turns out that they were binding their sight to the unsuspecting eagles that soar above the trees here. Using eagle vision, they were able to effectively spy on our every action.\n\nBy order of the lieutenant, we've got to hunt down these majestic birds in order to thwart our enemy.", sourceObjective = "Anderhol in Amberpine Lodge wants you to kill 5 Imperial Eagles and then report back to him.", completion = "A somber task, I know. But we can rest easier now knowing the enemy's eyes are no longer upon us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12218] = { id = 12218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spread the Good Word", description = "Before I can ship you off to Doctor Malefious with the good news, you will have to run a simple field test of the blight with the modifications I have made.\n\nThe hungering dead stream out from what remains of Old Wintergarde. Commandeer a vehicle from the east gate and drive it northeast through Vengeance Pass until you reach the twin towers at the southeastern edge of Wintergarde. Drop the blight bomb on the undead that cover the area. Report back to me with the results!", sourceObjective = "Chief Plaguebringer Middleton at Venomspite in Dragonblight wants you to use the Forsaken Blight Spreader's Blight Bomb to destroy 30 Hungering Dead on the outskirts of the Carrion Fields.", progress = "This test will be the final experiment in the series, {name}.", completion = "As much as it irritates me that we may have assisted the Alliance, I declare the field test a success! Next stop: Agmar's Hammer!", sourceObjectiveStatus = "unverified-source-field" }
quests[12219] = { id = 12219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Failed World Tree", description = "My ancestors once planted a tree in the middle of the Grizzly Hills.\n\nIt was called Vordrassil and it was to become a world tree.\n\nFor reasons long forgotten, after the tree was fully grown, they decided it needed to be destroyed.  Its giant trunk splintered at three locations in the area to the north.\n\nWhere the tree touched the ground, foul ooze began to crawl the earth.  Bring me slime samples so I can begin my work and the earth can be healed.", sourceObjective = "Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Limb, Vordrassil's Heart or Vordrassil's Tears and obtain 6 Slime Samples from the Entropic Oozes.", progress = "Have you gathered the samples, {name}?", completion = "The slime is not natural, {name}.  Its very nature is corrupt and... evil.\n\nWe must find out more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12220] = { id = 12220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dark Influence", description = "When the tree Vordrassil fell, its hollow remains grew roots deep into the ground.\n\nI want you to go north of here to the three locations where the trunk shattered and go as far beneath the ground as you can.  You'll find them west of Grizzlemaw.\n\nUse this orb once you get there to get an imprint of the energy surrounding the area.  If we're to heal the land, we must first find out what caused Vordrassil to fail as a world tree all those years ago.", sourceObjective = "Hierophant Thayreen at Amberpine Lodge wants you to go to Vordrassil's Heart, Vordrassil's Tears and Vordrassil's Limb and use the Geomancer's Orb in the depths beneath the surface.", completion = "The energy in the orb is... overpowering...\n\nA dark force has tainted the ground near Vordrassil's remains.  We will need to investigate more.", sourceObjectiveStatus = "unverified-source-field" }
quests[12221] = { id = 12221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forsaken Blight", description = "I have prepared a package that must be delivered to Doctor Sintar Malefious at Agmar's Hammer. The contents of the package include the final blight specimen along with instructions on preparation and samples of the reactive agent.\n\nYou will find Agmar's Hammer in western Dragonblight. Just look for the black, jagged metal orc buildings - that will be Agmar's Hammer.", sourceObjective = "Deliver The Forsaken Blight to Doctor Sintar Malefious at Agmar's Hammer.", progress = "About bloody time!", completion = "<Doctor Malefious looks through the contents of the package.>\n\nGlorious! Exactly to specifications!\n\nHere is your payment, {name}. Keep what you've seen and done to yourself. This work is all classified - information is given out on a need to know basis.", sourceObjectiveStatus = "unverified-source-field" }
quests[12222] = { id = 12222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Flamebinders", description = "Even as we attempt to fight off the Horde, the Dragonflayer tribe musters in their village of Voldrune, near the coast to the south.\n\nThe most powerful warriors in the village are granted flame-imbued talismans that give them the ability to control powerful, savage proto-drakes. If we can gain control of one of these drakes, perhaps we can use it to neutralize the threat posed by Voldrune.\n\nThe Dragonflayer flamebinders create the talismans and imbue them with power. Kill them and take the talismans.", sourceObjective = "Bring 3 Flame-Imbued Talismans to Woodsman Drake at Amberpine Lodge.", progress = "Did you collect those talismans?", completion = "With the talismans in hand, the drake will have no choice but to obey you. I can't wait to see the look on the thane's face when he realizes you've commandeered his proto-drake.", sourceObjectiveStatus = "unverified-source-field" }
quests[12223] = { id = 12223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thinning the Ranks", description = "There's a flurry of activity down in Voldrune village to the south. Thane Torvald Eriksson and his huscarls are preparing for war. With most of our men in the field dealing with the Horde's treachery, Amberpine will be vulnerable.\n\nTravel to Voldrune, which is near the southern coast, and show those Dragonflayers we're no soft target.\n\nSlay as many of the huscarls as you can find. Make them think twice about taking advantage of our conflict with the Horde.", sourceObjective = "Kill 12 Dragonflayer Huscarls and return to Woodsman Drake at Amberpine Lodge.", completion = "Well done, {name}. Now, we must follow through and press the advantage.", sourceObjectiveStatus = "unverified-source-field" }
quests[12224] = { id = 12224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Kor'kron Vanguard!", description = "You have done well, <brother/sister>. All that you have faced, you have done as a champion of the Horde. The Scourged Anub'ar of Azjol-Nerub, crushed under your foot! The taunka, brave and powerful new members of the Horde, because of you! Our super-weapon against the Scourge, tested and perfected by you!\n\nThe time has come, the moment is now - our elite soldiers at the Wrathgate need you. The son of Saurfang awaits your arrival at the Kor'kron Vanguard. Go now, northeast to the Wrathgate.", sourceObjective = "Report to Saurfang the Younger at the Kor'kron Vanguard.", completion = "Lok'tar ogar! I have heard much about you, {name}. Your battle scars run deep - a testament to your dedication and power!\n\nWith the flanking attacks of the Lich King crushed in both the west and east, only the forces at the gate remain. We gain ground each day, soon to break through this wall and into Icecrown!\n\nOnce we stop the skeletal dragons, Highlord Fordragon and I will take the field.", sourceObjectiveStatus = "unverified-source-field" }
quests[12225] = { id = 12225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mmm... Amberseeds!", description = "Your stomach growls as the pungent smell of hearty nuts draws your attention to the bucket of seeds.\n\nSome thoughtful soul has obviously left these complimentary morsels here to rejuvenate weary visitors. Grateful, you take the remaining few and devour them.\n\nThe seeds do not disappoint. Finding yourself hungry for more, you set out to discover their origins....", sourceObjective = "Speak with Master Woodsman Anderhol in Amberpine Lodge.", completion = "You did what!!!\n\nThose were Amberseeds! And that was an entire harvest's worth!\n\nThose magical seeds may have been the answer to our food crisis. Believe me when I tell you, {name}, you're going to make this right!", sourceObjectiveStatus = "unverified-source-field" }
quests[12226] = { id = 12226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Passing Through", description = "We must act quickly, {race}! We can't risk letting those precious seeds become fully digested. They need to come out, NOW.\n\nForage up some blackroot from the riverbank just west of here and I'll make you a purgative that should get things moving.\n\nHurry now! And remember, you brought this upon yourself....", sourceObjective = "Anderhol at Amberpine Lodge wants you to bring him 5 Blackroot Stalks.", progress = "Have you found the blackroot?", completion = "These should do just fine...\n\n<Anderhol deftly twists the stalks, collecting their slick fluids in a tiny vial.>\n\nThere we go, now it's time to get down to business.", sourceObjectiveStatus = "unverified-source-field" }
quests[12227] = { id = 12227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing Your Duty", description = "Alright, {race}. Here's the juice.\n\nIt works immediately, so don't use it until you're safely inside the outhouse.\n\nNow go get me those seeds!", sourceObjective = "Anderhol in Amberpine Lodge wants you to take the Anderhol's Slider Cider and use the nearby outhouse to retrieve the Partially Processed Amberseeds.", progress = "Got those seeds for me yet, {race}?", completion = "Well, {name}? Everything come out okay?\n\nHmm, looks like we caught 'em just in time....", sourceObjectiveStatus = "unverified-source-field" }
quests[12229] = { id = 12229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Possible Link", description = "Not long ago we sent an expedition to the east, where it was attacked by crazed furbolgs.  One of the survivors described slaying one of them and its body expelling a dark slimy substance.\n\nFor thousands of years, the furbolgs in this region have been peaceful.  It is possible that there is a link to the furbolgs' behavior and the dark energy we were able to detect earlier.\n\nBring me samples of the furbolgs' blood.  You will find them to the east in the Rage Fang Shrine and the Heart's Blood Shrine.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.", progress = "Have you obtained the blood samples, {name}?", completion = "This blood carries the same taint as the slime you obtained earlier... this does not bode well, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12230] = { id = 12230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stealing from the Siegesmiths", description = "I'm tasked with the destruction of the Scarlet Onslaught's ballistae. Unfortunately, the apothecaries and I are at odds on the use of our resources, so I've nothing to destroy them with!\n\nTo the northeast are the Carrion Fields. The Scourge siegesmiths there at their forge and meat wagons are demolition masters.\n\nLuckily for us, they also leave their bombs lying about. \n\nI want you to retrieve them for me, off of the ground or the siegesmiths, I don't care which.", sourceObjective = "Deathguard Molder at Venomspite has asked you to retrieve 6 Siegesmith Bombs.", progress = "You'd think that they'd let me make use of the blight spreaders... maybe load them up with something nasty to destroy the ballistae.\n\nBut no, they tell me that they're only for special missions.\n\nWhatever!", completion = "<The deathguard rubs his hands together in anticipation.>\n\nExcellent. Their loss is my... our gain!\n\nYou didn't have trouble with any of these along the way? Some of them look rather unstable. I may be undead, but I value my existence!", sourceObjectiveStatus = "unverified-source-field" }
quests[12231] = { id = 12231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bear God's Offspring", description = "It is possible that the furbolg of Grizzly Hills have the same taint that plagued Vordrassil.  They've been involved in a deadly tribal war recently after years of peaceful coexistence.\n\nThe shrines that they guard to the east are home to Ursoc's offspring.\n\nIf the corruption has affected the furbolg, it is possible that because of their lineage, Kodian and Orsonn have remained unharmed.\n\nIf that's the case, find them and listen to what they have to say.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to speak to Orsonn at the Ragefang Shrine and Kodian at the Heart's Blood Shrine.", completion = "Ursoc's children are wise.  Their words explain much of what we've seen so far.", sourceObjectiveStatus = "unverified-source-field" }
quests[12232] = { id = 12232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bombard the Ballistae", description = "At last, our chance to strike at their siege engines! Don't flub it.\n\nI kid.\n\nA little.\n\n{class}, bombard New Hearthglen's ballistae with these bombs.\n\nWe'll show the Royal Apothecary Society how it's done old style. No concoctions required!", sourceObjective = "Deathguard Molder at Venomspite has asked you to use the Siegesmith Bombs to bombard 5 New Hearthglen Ballistae.", progress = "Someday I'll be lead deathguard!\n\nSomeday....", completion = "Oh happy day!\n\nBy not using the time and resources of the apothecaries to get the job done, I'm sure to attract the attention of the high executor!\n\nThinking outside the box, that's what I'm all about. Yes, yes, you had a hand in helping too.\n\nHere, if I give you something will you promise to not mention your part in all of this?", sourceObjectiveStatus = "unverified-source-field" }
quests[12234] = { id = 12234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Need to Know", description = "I need to know what New Hearthglen is up to.\n\nI want you to steal their orders of the day so that I can find that out.\n\nHead south and in their abbey, in their barracks, and on their beach, find those daily plans!\n\nJust in case you're confused, the barracks is the large building right next to the smithy.", sourceObjective = "Spy Mistress Repine at Venomspite has asked you to steal the Scarlet Onslaught Daily Orders: Abbey, Scarlet Onslaught Daily Orders: Barracks, and Scarlet Onslaught Daily Orders: Beach.", progress = "If you take too long, their daily plans will change, and we may have to start over again.\n\nDon't take too long!", completion = "Well, what are you waiting for, {race}? Hand them over!", sourceObjectiveStatus = "unverified-source-field" }
quests[12235] = { id = 12235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Naxxramas and the Fall of Wintergarde", description = "Lord Fordragon has led a crushing assault against Arthas at the Wrathgate. In response to this affront, Arthas has sent Naxxramas down upon us. While Kel'Thuzad hides in the floating citadel, his ground commander, Thel'zan, lays siege to Wintergarde Keep. The lower village is already lost and any chance of extracting survivors from the ruins diminishes by the minute.\n\nWe must act quickly! Report to Gryphon Commander Urik at the gryphon station at once! He'll get you up to speed.\n\nLeave me!", sourceObjective = "Speak with Gryphon Commander Urik at the gryphon station in Wintergarde Keep.", completion = "<Urik points to a gryphon.>\n\nHave you ever ridden one of those? It's simple, friend. Just hop on and tell it where to go.", sourceObjectiveStatus = "unverified-source-field" }
quests[12236] = { id = 12236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, the Bear God", description = "The time has come, {name}.  Now we will learn whether our efforts will accomplish what we need or nothing at all.\n\nTake these ashes and seek the furbolg that Kodian told you about, Tur Ragepaw, near Ursoc's Den.  You will find the den to the north of Grizzlemaw.\n\nConvince Tur to aid you, for you will need all the help you can get.\n\nOnce you've defeated the bear god, use these ashes over his body.\n\nEven if his worldly form is destroyed, his spirit must be saved.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help. Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.", progress = "You've returned.  Did you succeed?", completion = "<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12237] = { id = 12237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flight of the Wintergarde Defender", description = "With this whistle you can call down a Wintergarde gryphon. Mount the creature and head towards the ruins of Wintergarde Village, now known as the Carrion Fields, southeast of here. Once at the fields, keep your eyes peeled for helpless Wintergarde villagers. When you spot one, fly low and use the gryphon to pick them up. Return the rescued villager here, to the gryphon station.\n\nThere are Scourge all over the place so you'll need to keep your wits about you, hero. Good luck!", sourceObjective = "Rescue 5 Helpless Wintergarde Villagers and return to Gryphon Commander Urik at Wintergarde Keep.", progress = "Hurry, {name}! You need to save the helpless villagers!", completion = "Outstanding work, {name}! We can get this keep back into working order now with the return of our citizens.", sourceObjectiveStatus = "unverified-source-field" }
quests[12238] = { id = 12238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleansing Drak'Tharon", description = "Drak'Tharon soon be cleansed of them foul undead and restored to her noble purpose. In return for your help, the keep's most valuable treasures be yours, mon!\n\nOnce ya be reachin' its top, ya must summon me, and I'll perform the ritual.\n\nAlas, my summonin' will be comin' at a cost. Ya must collect mojo from the survivors.", sourceObjective = "Drakuru wants you to use Drakuru's Elixir at his brazier inside Drak'Tharon. Using Drakuru's Elixir there will require 5 Enduring Mojo.", completion = "We done a great thing, mon! And dis just be da beginning....\n\nSeek me out in Zul'Drak when da time be right.\n\nDere be a war to be won, mon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12239] = { id = 12239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Spy in New Hearthglen", description = "I have a spy within the ranks of the Scarlet Onslaught. I need you to deliver these daily orders to her so that she can plan the next phase of our assault.\n\nShe goes by the name of Agent Skully and she's under a magical guise to appear as the Onslaught's cemetery caretaker.\n\nHere, take these orders to her, and then do as she asks. You'll find the graveyard on the side of the abbey.", sourceObjective = "Deliver the Scarlet Onslaught Daily Orders to Agent Skully at New Hearthglen.", progress = "<The agent eyes you up and down, and then silently motions you over.>\n\nDon't blow my cover, {class}!", completion = "You have word from the spy mistress?\n\n<The agent looks around to make sure that no one is watching as she puts down her shovel.>\n\nLet me see those plans.", sourceObjectiveStatus = "unverified-source-field" }
quests[12240] = { id = 12240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Means to an End", description = "I received a few barrels of termites from my sister at the Bulwark back home in the last shipment. I think they're going to come in handy for something I have in mind for you.\n\nThe lumbermill operations at New Hearthglen are problematic for us, but so far we haven't been able to get anyone in there to take out their foreman.\n\nI think that if you were to unleash these termites on his precious woodworks, he'd be sure to come running.\n\nReady to take him out, {class}?", sourceObjective = "Apothecary Vicky Levine at Venomspite has asked you to use the Levine Family Termites to lure Foreman Kaleiki out and kill him.", completion = "I knew my sister wouldn't let us down.\n\nWell done, {name}. The Onslaught's lumbermill will be out of commission for a while, which means no new construction or ballistae.\n\nThanks for helping me to live up to the family name.", sourceObjectiveStatus = "unverified-source-field" }
quests[12241] = { id = 12241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Destroy the Sapling", description = "The furbolgs' work must be undone, {name}.  The best of intentions do not count for much when the result is tainted by such strong a corruption.\n\nThe sapling must be destroyed, for it is the source of this dark influence.  Take this torch and use it to set fire to the corrupted sapling and bring me its ashes.\n\nOnce cleansed, by fire, I will use what power I can to remove the taint from them.  You will need the ashes to purify Ursoc from the evil power that holds sway over him.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling. Bring Vordrassil's Ashes back to Windseer Grayhorn.", progress = "Have you brought me the ashes, {name}?", completion = "I can't make any promises, {name}.  But I will try my best to purify these.", sourceObjectiveStatus = "unverified-source-field" }
quests[12242] = { id = 12242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Seeds", description = "We must make sure that Vordrassil is never regrown.  The furbolg must have harvested its seed.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain all the seeds that you can find.  I will make sure they're properly destroyed.", sourceObjective = "Windseer Grayhorn in Conquest Hold wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.", progress = "Have you obtained Vordrassil's seeds yet, {name}?", completion = "Thank you, {name}.  I'll take those from you.\n\nThe corruptive power of these seeds is dangerous.  I must destroy them right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[12243] = { id = 12243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Upon the Waters", description = "I have another mission for you.\n\nI was able to repurpose some of the blight to concoct my world-famous burning water. I want you to take it and set the sails of the Sinner's Folly ablaze!\n\nUse it from the dock. Once the sails are on fire, the deckhands will be busy putting them out, and you'll slip belowdecks to 'retrieve' the captain's rutters.\n\nYou'll find the ship on Crusader's Landing, below and south of New Hearthglen. Look for the captain's quarters on the first lower deck, behind the stairs.", sourceObjective = "Apothecary Vicky Levine at Venomspite has asked you to use her Apothecary's Burning Water to set the sails of the Sinner's Folly afire.\n\nWhile the deckhands are busy attempting to put the fires out, head belowdecks and retrieve Captain Shely's Rutters from the captain.", progress = "Please do NOT tell me that their sails were somehow protected from my burning water!\n\nI'd hate to have to test it out here again.", completion = "Ahhahahahahahahahaha!\n\nWithout their rutters, they've got nowhere to run to now.\n\nLooks to me like the end of the Scarlet Onslaught, and just when they were getting started. How sad.\n\nHeh.", sourceObjectiveStatus = "unverified-source-field" }
quests[12244] = { id = 12244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Repair", description = "Listen, pal. Why don't ya roll up your sleeves and grab a wrench? There's work to be done! They need these shredders refurbished and sent down to Venture Bay, and they need it done yesterday....\n\nNo wrench? Well what good are ya then? May as well go down with the rest of the lugheads and play with the Horde!\n\nWhile you're there, see if you can drive some of those broken-down shredders up here for repairs. Be careful! They're in pretty bad shape.", sourceObjective = "Synipus at Blue Sky Logging Grounds wants you to bring 3 Broken-down Shredders back to him.", progress = "No time for chit-chat. These shredders might tip the balance for the alliance!", completion = "<Synipus whistles.>\n\nOh, she's a beauty! We'll fix her up nice.\n\nIf you're short on things to do, go talk to Gordun and get a ride down to Venture Bay. They're sure to need a hand.\n\nOh, and while you're there, use these keys on a Refurbished Shredder. Wait 'til ya see what these babies can do when they're cleaned up!", sourceObjectiveStatus = "unverified-source-field" }
quests[12245] = { id = 12245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Mercy for the Captured", description = "We have more fools for you to kill.\n\nMy agents tell me that several of our good citizens have seen fit to fall into the hands of the Scarlet Onslaught.\n\nThis will not do.\n\nGo back to New Hearthglen and eliminate Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke and Chancellor Amai.\n\nFrom what I hear, they're spread out throughout the area. No doubt they are being kept in cages awaiting torture.\n\nSpeak with them and then kill them!", sourceObjective = "Spy Mistress Repine has asked you to slay Deathguard Schneider, Senior Scrivener Kinnedius, Engineer Burke, and Chancellor Amai.\n\nWhen you've accomplished this task, report your success to High Executor Wroth at Venomspite.", completion = "What? You were expecting us to have you rescue them?\n\nNow why would we do that when they have a proven track record of getting themselves captured in the first place?\n\nNorthrend is a cold place, young {name}. I suggest that you adjust to it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12246] = { id = 12246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Possible Link", description = "The furbolgs that live east of here are more aggressive and bestial than the ones we're used to.  Our forces have squared off with them more than once, and the survivors always speak of a dark, slimy substance dripping from their corpses.\n\nTheir condition could be linked with the contaminants we found on Vordrassil's remains.\n\nBring me samples of the furbolgs' blood.  You will find them in the Rage Fang Shrine and the Heart's Blood Shrine, far to the east.", sourceObjective = "Hierophant Thayreen at Amberpine Lodge wants you to obtain 8 Crazed Furbolg Blood from the Furbolgs at Heart's Blood Shrine and Rage Fang Shrine.", progress = "Have you obtained the blood samples, {name}?", completion = "The corruption present in this blood is identical to that of the slime.  I don't have a good feeling about this.", sourceObjectiveStatus = "unverified-source-field" }
quests[12247] = { id = 12247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Children of Ursoc", description = "The furbolgs of Grizzly Hills carry with them a corruption of some kind, that is for sure.  Tribal war has broken out amongst them after years of peaceful coexistence.\n\nWhat remains to be seen is whether the bears they worship as gods have also been tainted.\n\nUrsoc's two children, Orsonn and Kodian, dwell in the Heart's Blood Shrine and the Rage Fang Shrine, south and southeast of Grizzlemaw.\n\nSee if they will speak to you regarding what has happened here.", sourceObjective = "Hierophant Thayreen at Amberpine Lodge wants you to speak to Orsonn at the Rage Fang Shrine and Kodian at the Heart's Blood Shrine.", completion = "Ursoc's children are wise.  Their words explain much of what we've seen so far.", sourceObjectiveStatus = "unverified-source-field" }
quests[12248] = { id = 12248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Sapling", description = "The druids of old seem to have had good reasons for destroying Vordrassil.  We cannot let the furbolgs regrow it.\n\nOn the other hand, saving Ursoc's spirit hinges on the magic contained by the sapling.\n\nTake this torch and use it to burn the tree.  You will find it in the middle of Grizzlemaw, inside Vordrassil's old trunk.\n\nBring me Vordrassil's ashes.  It is my hope that once purified by fire, we may use its magic to cleanse Ursoc's spirit of its dark taint.", sourceObjective = "Hierophant Thayreen in Amberpine Lodge wants you to take the Verdant Torch and use it to burn Vordrassil's Sapling. Bring Vordrassil's Ashes back to Hierophant Thayreen.", progress = "Have you brought me the ashes, {name}?", completion = "Yes!  Vordrassil's magic is still present in these ashes.  There might be hope for Ursoc yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12249] = { id = 12249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ursoc, the Bear God", description = "It is time, {name}.  Take these ashes and look for the furbolg that Kodian spoke of.  If he went to seek Ursoc, he will be near his den, north of Grizzlemaw.\n\nYou will need his help.  You won't be able to defeat Ursoc alone.\n\nOnce you've defeated Ursoc, use these ashes to purify his spirit.  Only then will we know whether our efforts have been in vain or not.", sourceObjective = "Hierophant Thayreen at Amberpine Lodge wants you to find Tur Ragepaw near Ursoc's Den and defeat Ursoc with his help. Use the Purified Ashes of Vordrassil on Ursoc's Corpse when you've accomplished this.", completion = "<The druid looks pale and her eyes stare blankly past you.  She has left a package in anticipation of your return.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12250] = { id = 12250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vordrassil's Seeds", description = "We cannot allow Vordrassil to grow again.  If the furbolg regrew it once, they can do it again.\n\nGo to Grizzlemaw, in central Grizzly Hills, and obtain Vordrassil's seeds.  I will make sure they're properly disposed of.", sourceObjective = "Hierophant Thayreen at Amberpine Lodge wants you to go to Grizzlemaw and obtain 8 of Vordrassil's Seeds.", progress = "Do you have the seeds, {name}?", completion = "Thank you, {name}.  I'll take those from you.\n\nThe corruptive power of these seeds is dangerous.  I must destroy them right away.", sourceObjectiveStatus = "unverified-source-field" }
quests[12251] = { id = 12251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to the High Commander", description = "Return to High Commander Halford Wyrmbane at once, {name}. Let him know that your mission was a success and that the few remaining villagers that were rescued are back to work.", sourceObjective = "Speak with High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", completion = "<Halford salutes.>\n\nThe townsfolk are all back to work? Already? Outstanding, soldier! We'll get this town built back up and fortified in no time. Before long, reinforcements will be ready to join the fight with Lord Fordragon at the Wrathgate.\n\nI'm getting ahead of myself, of course, as there is much left to do here before we can even think about sending you to the aid of Bolvar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12252] = { id = 12252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torture the Torturer", description = "Enough! I want you to put an end to the torture of my people!\n\nThe Onslaught's torturer, Alphonse, has been bleeding information out of everyone that gets caught by those fiends! I need to know what they know.\n\nMy sources tell me that he has set up shop in the basement of their barracks, which is right next to the smithy.\n\nI'll loan you my personal branding iron to see to it that the job is done right.\n\nFind him and get that information.", sourceObjective = "High Executor Wroth at Venomspite wants you to use the branding iron 5 times on Torturer Alphonse to get the information out of him. After that, kill him.", progress = "What news do you bring? Success, no doubt?", completion = "They knew all of that? And who the hell is this Grand Admiral Westwind that he spoke of?!\n\n<The high executor grumbles to himself about hating surprises.>\n\nBetter that we know than have to guess. I hope that you left your... er, my mark.", sourceObjectiveStatus = "unverified-source-field" }
quests[12253] = { id = 12253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue from Town Square", description = "Just down this path here is Wintergarde's town square. Once a hive of activity for the citizens of Wintergarde, now a warzone, filled with murderous geists hell-bent on vengeance towards the living.\n\nIn the buildings surrounding the town square are trapped villagers that must be rescued! I ask much of you, now, {name}, but you are the only soldier I can spare. Free our people. Take this path down into town square and enter those houses. Kill anything that gets in your way! Return to me should you survive.", sourceObjective = "High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight wants you to rescue 6 Trapped Wintergarde Villagers.", completion = "<Halford says a prayer for the deceased.>\n\nYou do the Light's work, {name}.\n\nI fear that our work has only just begun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12254] = { id = 12254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Without a Prayer", description = "These plans indicate something imminent is being planned.\n\nBut first, there's the matter of this strange protection that the Onslaught forces have. If Venomspite is to deal with them once and for all, we must find out who's behind it and eliminate them.\n\nI've noticed that the bishop in the chapel on the far side of New Hearthglen, across from the lumbermill, has stepped up his blessing of the troops. Kill him and steal his prayer book.\n\nMaybe it will give us a clue.", sourceObjective = "Agent Skully at New Hearthglen has asked you to acquire Bishop Street's Prayer Book.", progress = "You have the bishop's prayer book? Did you find anything unusual in it?", completion = "A newly scribed blessing at the back of the book you say?\n\n<The agent glances over your shoulder as you flip to the page at the end.>\n\nDamn it all! That's the high abbot's handwriting! I'd stake your life on it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12255] = { id = 12255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thane of Voldrune", description = "Now that you've captured the flame-imbued talismans and weakened Voldrune's defenses, we can strike at its leader, Thane Torvald Eriksson.\n\nThe thane's favorite mount is an unruly proto-drake he calls Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the talismans, you should be able to control it long enough to use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and show him no mercy.", sourceObjective = "Use Flamebringer to defeat Thane Torvald Eriksson and report to Woodsman Drake at Amberpine Lodge.", progress = "Have you overcome the thane? We cannot risk leaving him in power.", completion = "Good work, {name}. I doubt any of the woodsmen would've wanted to take a crack at the proto-drake, but we couldn't afford to let the Dragonflayers build a base of power in Grizzly Hills. If only the Horde was so easily dealt with...", sourceObjectiveStatus = "unverified-source-field" }
quests[12256] = { id = 12256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Flamebinders' Secrets", description = "Even as the Alliance cowards attack our positions, the Dragonflayer vrykul outpost of Voldrune, to the southeast, prepares for war. The vrykul are far from the strongest enemy we face here, but we must eliminate them before they can truly threaten us.\n\nTheir most powerful warriors are permitted to ride half-trained proto-drakes into battle. To control the beasts, their flamebinders create powerful talismans. You'll need to slay them and take the talismans if our plan is to work.", sourceObjective = "Bring 3 Flame-Imbued Talismans to Sergeant Nazgrim at Conquest Hold.", progress = "Did you collect those talismans?", completion = "With the power of the talismans, the drake has no choice but to obey your commands. The thane's fate is sealed.", sourceObjectiveStatus = "unverified-source-field" }
quests[12257] = { id = 12257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Show of Strength", description = "Preparations for war are underway in the vrykul village of Voldrune to the southeast. Voldrune's thane cannot field a large army, but with our forces spread thin, we are still at risk.\n\nWe cannot risk giving the thane and his men an opportunity to attack, so we must take the battle to them. If you are truly a {class} of the Horde, you will relish the chance to demonstrate our strength.\n\nCut down the huscarls and prove to this Dragonflayer clan that the Horde is not to be trifled with!", sourceObjective = "Kill 12 Dragonflayer Huscarls and return to Sergeant Nazgrim at Conquest Hold.", completion = "You have done exactly as I asked. We've got the Dragonflayers on the defensive and it'll soon be time to deal with their leader.", sourceObjectiveStatus = "unverified-source-field" }
quests[12258] = { id = 12258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of the Dead", description = "The town square, down this path, is overrun with the undead citizens of Wintergarde! Our own crypt provides a seemingly endless supply of soldiers for the Scourge to throw at us. Take no pity on them, though, {name}. While they were once mortal, capable of compassion and thought, they are now ravaging undead with only one purpose: our destruction.\n\nVenture forth to the town square and deliver the vengeful geists to their maker. Give them peace.", sourceObjective = "Commander Lynore Windstryke at Wintergarde Keep in Dragonblight wants you to kill 15 Vengeful Geists.", completion = "Perhaps now they will rest easy, their spirits free to ascend to the Light.\n\nMy thoughts and prayers now turn to Lord Fordragon and our forces at the Wrathgate. We must persevere here, if only to buy them enough time to defeat the Lich King. Wintergarde cannot fall.", sourceObjectiveStatus = "unverified-source-field" }
quests[12259] = { id = 12259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Thane of Voldrune", description = "With the flame-imbued talismans, we can finally challenge the thane.\n\nHis favorite mount is a ferocious proto-drake called Flamebringer. It is kept bound in chains in the western part of Voldrune, but with the power of the talismans, you should be able to bend it to your will and use it against the thane.\n\nOnce you have Flamebringer under your control, search the tops of the towers of Voldrune for the thane and use Flamebringer to destroy him.", sourceObjective = "Use Flamebringer to defeat Thane Torvald Eriksson and report to Sergeant Nazgrim at Conquest Hold.", progress = "Have you overcome the thane?", completion = "The few remaining Dragonflayers dare not challenge us after your battle with the thane. Show no mercy to our enemies - that is the way of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12260] = { id = 12260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Perfect Dissemblance", description = "You may wonder how I can maintain this guise; I use a magic mirror that was loaned to me by the spy mistress.\n\nIt only has so much power in it, but I think there's enough for the both of us. Here, take it. I want you to use it to impersonate one of the Onslaught raven priests.\n\nBe quick about it... I have no idea how long my glamour will last while you have the mirror.\n\nRealize that you won't immediately be perfectly disguised, so don't count on it being foolproof until I've had a chance to help you.", sourceObjective = "Agent Skully at New Hearthglen has asked you to steal the image of an Onslaught Raven Priest. Return the Banshee's Magic Mirror to her when you have done so.", progress = "Please tell me that you didn't break the mirror?!", completion = "Not bad, {class}. Now that the priest's image is trapped within the mirror, I have something else that needs doing.", sourceObjectiveStatus = "unverified-source-field" }
quests[12261] = { id = 12261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Place to Run", description = "They're drawing power from the bones of my dead brothers...\n\nI have no love for the cult, but I'm baffled by their audacity. There will be no mercy shown for them... not that I ever would have anyway.\n\nEnsure that they have no place to flee when the slaughter starts. Place a destructive ward at the end of the path leading out of the shrine... where the road starts to give way to snow. Defend it until it is fully charged.", sourceObjective = "Place a Destructive Ward at the end of the path leading out of Obsidian Dragonshrine, where the road starts to give way to snow. Protect the ward until it is fully charged, then return to Serinar.", progress = "Have you placed the ward?", completion = "Excellent. When they begin to flee in fear, the ward shall be there to wish them a fond farewell.", sourceObjectiveStatus = "unverified-source-field" }
quests[12262] = { id = 12262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No One to Save You", description = "We will spare no one. \n\nOutside, lowly necrolytes and their skeletal servants shame my land with their presence. Slaughter them all.", sourceObjective = "Kill 6 Burning Depths Necrolytes and 10 Smoldering Skeletons outside of the Obsidian Dragonshrine. Return to Serinar once the task is complete.", progress = "I see the blood on your hands... it is done then?", completion = "Did they beg for their miserable lives? Weaklings.", sourceObjectiveStatus = "unverified-source-field" }
quests[12263] = { id = 12263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best of Intentions", description = "The Cult of the Damned has not come just to extract power from dead dragons. I suspect I know what they are up to, but I need you to prove me correct.\n\nI will grant you the guise of this dead necrolyte. Proceed to the back of the cave and confirm their intentions for being in this sacred place. I will watch through your eyes. \n\nBe cautious {name}, any damage done to you is likely to break the fragile illusion.", sourceObjective = "Wait for Serinar to administer the disguise of a Burning Depths Necrolyte, then proceed to the back of the Maw of Neltharion to uncover what the Cult of the Damned is doing there. Return to Serinar with details regarding their purpose.", progress = "I tire of this pestilence.", completion = "We are the Black Dragonflight. We have rained destruction on the lands of Azeroth for thousands of years. The decrepit Cult of the Damned worships death and we shall be glad to oblige.", sourceObjectiveStatus = "unverified-source-field" }
quests[12264] = { id = 12264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Culling the Damned", description = "The cave beyond was swarming with Cult atrocities. There is only one way to deal with such creatures... you know what to do.", sourceObjective = "Kill 3 Burning Depths Necromancers, 6 Smoldering Constructs, and 6 Smoldering Geist in the Maw of Neltharion, and then return to Serinar.", progress = "I cannot help but wonder whether they are naive enough to think that I will abide this or if they are simply suicidal.", completion = "Hearing their screams... watching the last life fade from their wretched bodies... it's invigorating, is it not?\n\nI relish it.", sourceObjectiveStatus = "unverified-source-field" }
quests[12265] = { id = 12265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defiling the Defilers", description = "I sensed a large accumulation of magic in the runes that we witnessed when you were scouting the cave. I will not have you toy with extracting the magic... often the most straight forward solution is the most effective one.\n\nDestroy the runes... stamp them out and ensure that the Cult will not have access to whatever power that they've accumulated there.", sourceObjective = "Locate and stamp out 8 Necromantic Runes that have been drawn on the floor inside the Maw of Neltharion. Return to Serinar once the task is complete.", progress = "Power wasted on the weak and the useless.\n\nShow me a being worthy of the life and magic they have been gifted, and then perhaps we can talk of waste before extinguishing their presence.\n\nDon't worry, I'll wait.", completion = "Good. There is more to be done.", sourceObjectiveStatus = "unverified-source-field" }
quests[12266] = { id = 12266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tales of Destruction", description = "You can leave now, {race}.\n\nGo tell Nalice she missed out on a good slaughter.", sourceObjective = "Travel back to Wyrmrest and let Nalice know that Serinar's task is complete.", completion = "Oh, it's you.\n\nI had hoped Serinar would simply return himself once the task was done... I suppose he's distracted by something or another to kill. He's missing out on a gloriously messy battle!\n\nAre you still here? I'm done with you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12267] = { id = 12267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharion's Flame", description = "With the cult's ranks thinned and some of their power stripped, it's time to strike at the source of the corruption.\n\nRothin the Decaying is resurrecting black dragons as magmawyrms in the back of the cave. Go to the summoning chamber and cleanse the remaining bones in the only way that will ensure that they will never be toyed with again... with flame.\n\nBurning the bones will surely gain Rothin's attention, see to it that he is destroyed as well.\n\nThe magic in this vial should see the task done.", sourceObjective = "Use Neltharion's Flame to douse the summoning area in the back of the Maw of Neltharion. Once you get the attention of Rothin the Decaying, kill him, then return to Serinar at the front of the cave.", progress = "You are quite an effective tool, {class}. Your hand in this purging is appreciated.", completion = "The bones of my brood have been spared this filth. You have served me well, and as such, you shall be awarded appropriately.", sourceObjectiveStatus = "unverified-source-field" }
quests[12268] = { id = 12268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pieces Parts", description = "Ack! This thing's a mess!\n\nGoblin engineering leaves a great deal to be desired, believe you me. Just look at this! It's a wonder it ever worked to begin with.\n\nGive me a hand, will ya? To get this even close to operable specifications I'll need to replace a few cogs, sprockets, and springs. You should have no trouble finding them down around the sawmill.", sourceObjective = "Pipthwack in Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.", progress = "Got those parts for me, {class}?", completion = "Yes indeed. These should do the trick...\n\nThere. One more shredder ready for the fight. Thanks, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12269] = { id = 12269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not In Our Mine", description = "That blasted necropolis blindsided us! In the wake of its destruction Wintergarde Mine was lost. Worse yet, Kel'Thuzad's acolytes have raised the slain miners as Scourge and are using them to supply their siegesmiths with materials from our mine!\n\nThe supply line must be halted and our lost brothers must be put to rest.\n\nTravel to Wintergarde Mine, northeast of here in the Carrion Fields, and destroy the risen miners. Return to me with their miner cards so that I may put their passing in our registry.", sourceObjective = "Highlord Leoric Von Zeldig at Wintergarde Keep in Dragonblight wants you to recover 10 Wintergarde Miner's Cards.", progress = "Did you recover their cards?", completion = "<Leoric takes the cards from you.>\n\nI will get these to our recorder and deliver the grim news to the families of the miners.\n\nThere is still much to be done if we are to succeed here and ultimately at the Wrathgate. Lord Fordragon is depending on us.", sourceObjectiveStatus = "unverified-source-field" }
quests[12270] = { id = 12270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shred the Alliance", description = "Read my lips, {class} - I need those shredders! Just as important - I need to keep them out of the hands of the Alliance!\n\nThey've been refurbishing the shredders and using them against our brothers in Venture Bay. Now we're going to give them a taste of their own medicine!\n\nYou see a shredder out there, grab it! You see one of the Alliance scum on one, kill 'em and then grab it! Once you have one, drive it back here to me and we'll get to work on it.\n\nDismissed!", sourceObjective = "Grekk at Blue Sky Logging Grounds wants you to acquire 3 shredders and return to him with them.", progress = "Get me those shredders yet, {class}?", completion = "Good work, soldier!\n\nNow take this key and get yourself down to Venture Bay. It'll let you use one of the refurbished shredders to unleash chaos on our enemies.\n\nOh yes, and talk to Darrok if you want to take the shortcut!", sourceObjectiveStatus = "unverified-source-field" }
quests[12271] = { id = 12271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rod of Compulsion", description = "A rod drops from Alphonse's dead hand. There are pulsing magical runes along its length.\n\nCould this be how he was getting his confessions?\n\nBetter let the high executor have a look at it.", sourceObjective = "Deliver the Torturer's Rod to High Executor Wroth at Venomspite.", progress = "Did you get that rod from their torturer?", completion = "Alphonse had it you say? That makes sense.\n\nI recognize it from my youthful days as a torturer in the court of King Terenas of fallen Lordaeron. It's known as a rod of compulsion.\n\n<The high executor wrings his hands together in evil anticipation of what's to come.>\n\nI have an idea for how we can make good use of it!", sourceObjectiveStatus = "unverified-source-field" }
quests[12272] = { id = 12272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bleeding Ore", description = "Hours before the Naxxramas invasion, one of the miners stumbled upon a dark ore that was oozing a viscous fluid. In the chaos that occurred during the evacuation of the mine, we lost the samples taken from the alien node. Now the Scourge prospects the ore for use in their machines of death.\n\nYou must get back to Wintergarde Mine, due northeast of here in the Carrion Fields, and recover the strange ore. It is imperative to our mission's success!", sourceObjective = "Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight wants you to recover 10 samples of Strange Ore from Wintergarde Mine.", progress = "Have you recovered samples of the strange ore?", completion = "This might be the moment, the very second, that the tide turns against the Scourge. You have proven yourself as a hero of the Alliance, at least in my eyes, {name}.\n\nNow if you would be so kind as to give me some space. I will require additional time to study this ore in order to isolate impurities and weakness.\n\nCarry on, ally. I will contact you once I have an update.", sourceObjectiveStatus = "unverified-source-field" }
quests[12273] = { id = 12273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Denouncement", description = "It's time for us to utterly demoralize the Onslaught forces!\n\nI want you to take the rod and use it on four of their leaders: Commander Jordan upstairs at the barracks, Lead Cannoneer Zierhut down the southeast ramp overlooking the beach, Blacksmith Goodman at the smithy, and Stable Master Mercer at the stables.\n\nPlace them under the rod's compulsion, concentrate on making them denounce the Onslaught, and then kill them!", sourceObjective = "High Executor Wroth at Venomspite has tasked you with using the Rod of Compulsion on Commander Jordan, Lead Cannoneer Zierhut, Blacksmith Goodman, and Stable Master Mercer.\n\nOnce the rod has been used on them, kill each to exact a denouncement of the Scarlet Onslaught as their final words.", progress = "Well?!", completion = "<You think you see just the hint of a smile cross Wroth's face before quickly disappearing.>\n\nYou're now my favorite {class}, {name}. If you have a mind to, I'd like you to think about joining up as an officer in the Hand of Vengeance.\n\nWe can start you out as a deathguard, and in a few decades I think you have what it takes to make junior executor!\n\nNo? Well don't be too hasty... take your time and mull it over.", sourceObjectiveStatus = "unverified-source-field" }
quests[12274] = { id = 12274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fall From Grace", description = "We need more information from the high abbot, and now that we have the visage of one of the raven priests, I think we can get you close to talk with him.\n\nUnfortunately, we need to separate him from his bodyguards or you'll never get any information out of him.\n\n<The agent leans on her shovel and thinks a moment.>\n\nI think I've got it! While in disguise, go to the top of the abbey and ring the bell. That should bring the abbot's bodyguards running and you can then head down to speak with him.", sourceObjective = "Agent Skully at New Hearthglen has asked you to ring the bell in the abbey and then go speak with the high abbot and get information out of him.", progress = "What did you find out? Have you even talked with him yet?", completion = "What the hell is going on here?!\n\nHe jumped on his own? You're certain that you didn't push him?\n\n<The agent narrows her eyes at you.>\n\nFine. Clearly there's much more going on in this place than we first thought.", sourceObjectiveStatus = "unverified-source-field" }
quests[12275] = { id = 12275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Demo-gnome", description = "Quarterflash recently requisitioned my group for a specialist that he could send on a reconnaissance mission to the Wintergarde Mine. To that end, I sent him Slinkin, my demolitionist. I foolishly thought that he could close off that pit of damnation after his mission for Quarterflash was complete, securing another victory for us against the Scourge.\n\nAn entire day has now passed and Slinkin has not returned. I want answers! Speak with Siege Engineer Quarterflash and track down my missing agent!", sourceObjective = "Speak with Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight.", completion = "I feel terrible about this, friend. I fear that in my haste to recover the strange ore from Wintergarde Mine I may have doomed agent Slinkin.", sourceObjectiveStatus = "unverified-source-field" }
quests[12276] = { id = 12276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search for Slinkin", description = "While I have not heard from Slinkin or know what fate has befallen him, perhaps I can assist in finding him.\n\n<Quarterflash holds up a tiny mechanical toy.>\n\nThis is not a toy, newfound compatriot. It is, in fact, my latest mechanical creation. The machine was created with the sole purpose of finding that which has been lost. These are unfortunate circumstances, but the machine is your best chance at finding Slinkin.\n\nWhen you are ready to begin your search, place the bot on the ground next to me.", sourceObjective = "Find Slinkin the Demo-gnome in Wintergarde Mine. Use Quarterflash's Homing Bot if you need help finding the mine.\n\nProvided item:", completion = "<There is a note in Slinkin's death grip.>\n\nChased into a dead end. Hidden for now, but they know I'm here. It won't be long until they find me.\n\nThe miners work tirelessly to unearth the strange ore that fuels the Scourge war machines. There is much banter. The language of death confounds me, but I have been able to identify commonly uttered sounds and phrases. The word \"Yogg-Saron\" is said with great contempt and is usually followed by loud outbursts. They refer to the ore as \"saronite.\" Meaning?", sourceObjectiveStatus = "unverified-source-field" }
quests[12277] = { id = 12277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Nothing to Chance", description = "If there is good in your heart and your conscience is clear, read on.\n\nIn this mine, near the foreman's scaffold, rests a hefty cargo of dynamite. Go there and pick up several bundles of the explosive and make your way towards the entrance of the mine. Once there, set the dynamite and blow up the entrance. Remember to do this for the upper and lower entry points of Wintergarde Mine.\n\nYou must leave nothing to chance. The evil that exists here must never be allowed out. Light guide you.", sourceObjective = "Retrieve a Wintergarde Mine Bomb and use it to blow up the Upper Wintergarde Mine Shaft and the Lower Wintergarde Mine Shaft. Report back to Siege Engineer Quarterflash at Wintergarde Keep in Dragonblight when you have completed this task.", progress = "<Quarterflash nods.>\n\nHe was a good gnome, one of our best. Slinkin will be missed.", completion = "His death will not have been in vain, friend. The information that Slinkin died for will be instrumental in defeating the Lich King. I promise you that we will make this right.", sourceObjectiveStatus = "unverified-source-field" }
quests[12278] = { id = 12278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", sourceObjective = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, {name}!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving.", sourceObjectiveStatus = "unverified-source-field" }
quests[12279] = { id = 12279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bear of an Appetite", description = "Thank goodness you're back, Limpy! I worried that Griselda and I were going to be all alone.\n\nI'm cooking up some food here for us, but Griselda'll have none of it.\n\nShe's fond of the fish that live off the coast of the Eastwind Shore, to the east. Can't stand them myself, but she's always been a picky eater. Six good-sized fish ought to keep her happy for a while.\n\nNow, run... err... limp along, Joe. Wouldn't want to keep the girl waiting, would ya?", sourceObjective = "Bring 6 Northern Salmon to Hugh Glass at the Redwood Trading Post.", progress = "If you don't hurry, it'll be more than just her stomach growling...", completion = "You! You're not Limpy Joe!", sourceObjectiveStatus = "unverified-source-field" }
quests[12280] = { id = 12280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Making Repairs", description = "Twenty shredders by noon tomorrow!\n\nWho makes these schedules, anyway? No one who ever put one of these garbage cans back together, that's who....\n\nIf I'm going to hit my quota, I'll need a hand. Help me out and I'll share my commission with you - fair enough?\n\nI need cogs, sprockets and springs. They're littered across the ground down by the shredders.", sourceObjective = "Lurz at Blue Sky Logging Grounds wants you to collect 4 Grooved Cogs, 3 Notched Sprockets, and 2 High Tension Springs.", progress = "Ya fetch those parts for me yet?", completion = "Thanks, {name}. That should keep me going - at least until tomorrow....\n\nHere's the cash I promised.", sourceObjectiveStatus = "unverified-source-field" }
quests[12281] = { id = 12281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Scourge War Machine", description = "We must take solace in the fact that Slinkin's death, while tragic, was for the greater good. His discovery coupled with your heroics in the mine and the samples you returned brings us one step closer to understanding the Scourge war machine.\n\nTake this package to High Commander Halford Wyrmbane. It holds a sample of the strange ore and my analysis.", sourceObjective = "Deliver Quarterflash's Package to High Commander Halford Wyrmbane at Wintergarde Keep.", progress = "I heard about your bravery in the mine, {name}.", completion = "<Halford opens the package and reads the analysis.>\n\nI am by no means a scientist, {name}, so you'll have to forgive my plebian understanding of what has been written. Now, according to this analysis - assuming I have the brain power of at least an adolescent school boy - we still don't know jack squat about the Scourge war machine. The only thing we do know is that the Scourge uses this foul metal to craft its siege engines, armor and weaponry.", sourceObjectiveStatus = "unverified-source-field" }
quests[12282] = { id = 12282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Imprints on the Past", description = "The memories of the past haunt this land, {name}. I hear the cries of the fallen echo across Northrend - calling to me.\n\nArthas left a terrible imprint on everything he touched. Only wither and decay remains in his wake. It is important, then, for us to study the past so that we may better know our enemy. Perhaps untold truths shall surface that could help in our campaign.\n\nFirst, you must recover my scrying orb from the town hall, {name}. Exit this tower and turn left down the path to reach the town square.", sourceObjective = "Zelig the Visionary at Wintergarde Keep in Dragonblight wants you to recover his Scrying Orb.", progress = "Have you recovered my scrying orb?", completion = "Well done, {name}. As fate foretold, you will be the one to carry us through these hard times. Now the long journey begins.", sourceObjectiveStatus = "unverified-source-field" }
quests[12283] = { id = 12283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth Will Out", description = "We have to figure out what's going on here. We need the general's diary!\n\nI'm pretty sure that you'll find it on her nightstand upstairs at her house. It's the one next to church, across from the stables and the lumbermill.\n\nOnce you acquire the diary, take it to the high executor back at Venomspite.\n\nYou'll have to do this the old-fashioned way; the power of the mirror is low and there's only enough left for me.\n\n<The agent smirks.>", sourceObjective = "Agent Skully has asked you to acquire The Diary of High General Abbendis and to deliver it to High Executor Wroth at Venomspite.", progress = "It's about time, {name}! What's been keeping you?", completion = "Damn it all! Why couldn't you have come to me with good news?!", sourceObjectiveStatus = "unverified-source-field" }
quests[12284] = { id = 12284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep 'Em on Their Heels", description = "We've suffered heavy casualties here, {race}.\n\nThe only good news is that we've given as much as we've taken. I've requested more troops, but the bulk of our forces are bogged down in Venture Bay. It looks like we're on our own for now.\n\nNo matter how bad it gets, we MUST stand our ground! The precious resources of this region are essential to the Horde's long-term success in Northrend.\n\nWe've got to keep the Alliance on their heels until help arrives. Get out there and give 'em something to think about.", sourceObjective = "Commander Bargok wants you to kill 15 Alliance units or players in Blue Sky Logging Ground.", completion = "Fifteen down, eh? Good to hear it, {class}.\n\nIf nothing else you've bought us a bit of time - at least a day by my figuring.\n\nHere's your pay.", sourceObjectiveStatus = "unverified-source-field" }
quests[12285] = { id = 12285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do Unto Others", description = "Their attack is imminent, {class}. I need you to get in there and sever the head of the Scarlet Onslaught, literally!\n\nIt's not going to be easy... Abbendis is sure to be surrounded by a great many of her men.\n\nBring back her head and I'll see to it that you're properly rewarded for saving Venomspite.\n\nFail and don't even bother to return!", sourceObjective = "High Executor Wroth at Venomspite has ordered you to return with The Head of the High General.", progress = "Should I tell my forces to begin making our way toward Agmar's Hammer?\n\nOr did you manage kill the high general?", completion = "Let's see them bring her back to life without her head!\n\n<The high executor's laugh draws a number of furtive glances.>\n\nI'm a little concerned that you let this grand admiral get away, but you're still the hero of the day, {name}!\n\nTake your pick... you've earned it!", sourceObjectiveStatus = "unverified-source-field" }
quests[12286] = { id = 12286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
quests[12287] = { id = 12287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orik Trueheart and the Forgotten Shore", description = "I have gazed upon the orb and seen the path that you must walk, {name}.\n\nMany years ago an atrocity was committed upon the shores of Dragonblight. The act itself remains shrouded in darkness, but I am certain that your destiny lies south, amidst the ruins of the Forgotten Shore.\n\nTake the road southeast through the ravaged town square. Follow the trail until you arrive at Dawn's Reach. You will meet an old friend of mine there known as Orik Trueheart. He will be expecting you.", sourceObjective = "Seek out the assistance of Orik Trueheart at Dawn's Reach in Dragonblight.", completion = "Zelig sent word, friend. We have been expecting you.\n\nI am Orik Trueheart, paladin of the Argent Crusade. The priestess standing across the campfire from me is Tilda Darathan. We are here on behalf of the Argent Crusade - sent to quell the unfortunate damned souls attempting to escape Wintergarde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12288] = { id = 12288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Overwhelmed!", description = "You there, {class}! Help me!\n\nWe're losing valuable lives! There are simply too many wounded for me to tend to alone. If we can't get our soldiers healed we could be run out of Grizzly Hills altogether!\n\nTake this tourniquet and use it on the wounded down on the battlefield.\n\nHurry, {name}! They're dyyying!!", sourceObjective = "Aumana at Blue Sky Logging Grounds wants you to use the Renewing Tourniquet on 10 Wounded Skirmishers.", progress = "Have you healed our wounded yet, {name}?", completion = "Oh, thank you, thank you.\n\nYou've helped us to live another day. Perhaps there's hope yet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12289] = { id = 12289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kick 'Em While They're Down", description = "It is a dark day for the Alliance. Many good men lay dead or dying here. Our only consolation is that they fought well and brought down many of the enemy with them.\n\nWith the bulk of our forces committed to Venture Bay we stand alone to weather this storm. The resources in this region are vital to the Alliance and may well make the difference in our struggle against the Horde. We must not fail!\n\nGo, {name}. Strike at them while they lick their wounds. Avenge your fallen brothers and keep our hopes alive!", sourceObjective = "Sergeant Hartsman wants you to defeat 15 Horde units or players in Blue Sky Logging Grounds.", progress = "How goes the fight, {name}?", completion = "Well done, {name}.\n\nYou've bought us some time here, though likely no more than a day. Nevertheless, the Alliance is grateful for your efforts.", sourceObjectiveStatus = "unverified-source-field" }
quests[12290] = { id = 12290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Murkweed Elixir", description = "The spirits of the damned haunt the coast. In life they were brave and noble soldiers of the Alliance, but in death they are cursed - bound to this world until the end of days. We must discover the source of their anguish if we are to free them!\n\nTo the southeast, on the Eldritch Heights, you will find a rare herb known as murkweed. It is murkweed that I will use to concoct an elixir that will allow you temporary entry into the world of the forgotten. Go now and gather the weed.", sourceObjective = "Orik Trueheart at Dawn's Reach in Dragonblight wants you to recover 5 Murkweed from the Eldritch Heights.", progress = "Have you recovered the murkweed?", completion = "<Orik takes the murkweed and begins mixing an elixir.>\n\nIt won't be much longer, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12291] = { id = 12291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forgotten Tale", description = "The toxins in the murkweed elixir will render you unconscious. So powerful is the effect of the murkweed that even your spirit will be fooled, allowing you to temporarily enter the world of the dead.\n\nOnce a spirit, you must speak to the ghostly denizens of the Forgotten Shore. Seek out the cause of their anguish and return to me.\n\nRemember, {name}, these spirits were once Alliance soldiers. Treat them with respect, honor and dignity.\n\nNow, with elixir in hand, venture south to the Forgotten Shore.", sourceObjective = "Orik Trueheart at Dawn's Reach in Dragonblight wants you to hear the tales of a Forgotten Peasant, Forgotten Rifleman, Forgotten Knight and Forgotten Footman.", progress = "I have enough murkweed to make more elixirs, {name}.", completion = "<Orik's eyes fill with tears.>\n\nThey don't know. None of them know! They think Arthas to be some great hero, when in truth it was Arthas who ordered the ships to be burned. It was Arthas who left us all for dead in this frozen wasteland!\n\n<Orik weeps.>\n\nNot all of the soldiers from the Prince's fleet perished in the freezing winter. I was only a lad when I was given the chance to battle the Scourge... to save our home from certain destruction. I took that chance, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12292] = { id = 12292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Local Support", description = "We've reached a deadlock with the Horde in Grizzly Hills.  Our forces are just about evenly matched and all signs so far have pointed to a stalemate.\n\nUntil this morning, that is.  The local trappers have requested our help.  Apparently the Horde took something that belongs to them... a relic of some sort.\n\nWe get this back for them and they'll give us the edge we need.  Head to the Evergreen Trading Post, west of Conquest Hold and look for a cedar chest.", sourceObjective = "Lieutenant Dumont at Amberpine Lodge wants you to go to Evergreen Trading Post and obtain the Cedar Chest.", progress = "You bring me that box, {name}?", completion = "It's locked, isn't it?  It looks pretty ordinary.\n\n<Lieutenant Dumont Shakes the chest, producing a rattling wooden sound.>\n\nNo matter, I suppose.  If this gets us the edge we need against the Horde, then I could care less if the cure for the Plague was in there.", sourceObjectiveStatus = "unverified-source-field" }
quests[12293] = { id = 12293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Close the Deal", description = "We have what the trappers want.  Now it's up to us to sign them up with our side.\n\nTake the chest to a trapper named Ivan at the Aspen Grove Post, just north of here.\n\nIf all goes well, we'll have local woodsmen serving as scouts for the king's army in no time.", sourceObjective = "Bring the Cedar Chest to Ivan at Aspen Grove Post.", progress = "You've brought something for us?", completion = "You did it!  You recovered the Sc... you recovered the chest that the Horde stole from us.  We thank you, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12294] = { id = 12294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Tentative Pact", description = "Very well, {name}.  Your people kept their end of the bargain.\n\nTell Dumont that we'll honor the deal.", sourceObjective = "Return to Lieutenant Dumont in Amberpine Lodge.", completion = "Excellent news, {name}.  With the locals' help we'll have the logistical support we need to outmaneuver the Horde in this region.\n\nI have further tasks for you if you're interested.", sourceObjectiveStatus = "unverified-source-field" }
quests[12295] = { id = 12295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exercise in Diplomacy", description = "We'd been trying to negotiate with the trappers for weeks, but we'd gotten nowhere until you found that blasted chest of theirs.\n\nThis should be good news to our envoy in Silverbrook.  We sent Ducal there about a week ago and his last letter indicated he'd been making little progress.\n\nGo to Silverbrook and aid him in his diplomatic efforts.  Take the roads heading northwest of here and you should find it after crossing a couple of bridges.", sourceObjective = "Speak to Envoy Ducal in Silverbrook.", completion = "It's good to finally meet you, {name}!  We'd heard about you up here.  Welcome to Silverbrook.\n\nThese trappers are a great bunch of lads and lasses.  Hardy people, they know the lay of the land really well.  You'll find it's a great thing that we finally won them over to our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[12296] = { id = 12296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Life or Death", description = "Oh, the carnage....\n\nI've been through many battles, {class}, and this one was more brutal than any I've seen. Our fight with the Horde has become more intense than ever. It's them or us here in Northrend - life or death.\n\nIf we are to survive here another day we'll need to mend our wounded. There are too many for me to rescue alone.\n\nI've prepared special bandages that will enable you to assist me. Take one and tend to those who have not yet succumbed to their wounds.", sourceObjective = "Rheanna at Blue Sky Logging Grounds wants you to use the Renewing Bandage on 10 Wounded Westfall Infantry units.", completion = "Wonderful!\n\nThe Alliance shall live to see another day, in part due to your diligence.\n\nPlease accept my thanks, friend.", sourceObjectiveStatus = "unverified-source-field" }
quests[12297] = { id = 12297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Of Traitors and Treason", description = "The list I hold must be delivered to High Commander Halford Wyrmbane. He commands the 7th Legion, stationed at Wintergarde Keep on the eastern borders of the Great Dragonblight.\n\nIf any of the traitors on this list are stationed at Wintergarde... it could be catastrophic.\n\nHurry, {name}. Show the document to Greer Orehammer here at Westguard Keep and explain the nature of your mission. He'll put you on his fastest gryphon to Wintergarde!", sourceObjective = "Captain Adams has asked you to show the Alliance Missive to Greer Orehammer at Westguard Keep.", progress = "Hello, {class}.", completion = "<Greer lifts his glasses onto the top of his head and reads the note, looking back up at you curiously when he's done.>\n\nYou will have my fastest gryphon! This information must be delivered to High Commander Wyrmbane at once!", sourceObjectiveStatus = "unverified-source-field" }
quests[12298] = { id = 12298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "High Commander Halford Wyrmbane", description = "<Greer hands the missive back to you.>\n\nSkysong will take you to Wintergarde, {name}. I guarantee you that it will be the fastest flight you've ever taken. Go now!", sourceObjective = "Deliver the Alliance Missive to High Commander Halford Wyrmbane at Wintergarde Keep in eastern Dragonblight.", progress = "What have you got there, soldier?", completion = "<The High Commander reads the missive and then crumples it up.>\n\nDo you know where the people on this list are now? Take a look outside, near the front gate. They're the ones hanging from the arches.\n\nGhoul bait...", sourceObjectiveStatus = "unverified-source-field" }
quests[12299] = { id = 12299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northern Hospitality", description = "It's good to meet you.  Let us celebrate our pact by partaking in some good old fashioned Horde-killing.\n\nYou'll find marauders from Conquest Hold just outside our town, west of here.  Why don't you head out there and hunt them like the filthy animals they are?\n\nLet's see if our new allies can back all their talk with some action.", sourceObjective = "Sergei at Silverbrook wants you to slay 8 Conquest Hold Marauders.", progress = "You done with those Horde cretins yet?", completion = "Not bad, not bad.  You might not be as soft as some of the others.", sourceObjectiveStatus = "unverified-source-field" }
quests[12300] = { id = 12300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test of Mettle", description = "Alright, friend.  You've done us a favor or two, but that's not the true test of a person's courage.\n\nAround these parts, you're not a real hunter unless you wear your prey's skin.\n\n<Sergei unsheathes his skinning knife and hands it to you.>\n\nThe leader of those motherless orcs attacking our town is called Bonesnap; you'll find him at a camp further northwest.\n\nThat's right.  You're going to skin the monster.", sourceObjective = "Find Sergeant Bonesnap northwest of Silverbrook and pass the Test of Mettle.", progress = "The people in Silverbrook... they're not what they seem.", completion = "Don't do it, {name}.  The people that sent you here.... you shouldn't trust them.", sourceObjectiveStatus = "unverified-source-field" }
quests[12301] = { id = 12301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Truth Shall Set Us Free", description = "Zelig gave this crystal ball to me years ago with specific instruction on its use. For five years - whenever I would feel anger, anxiety, or sorrow over the events that transpired here - I was to focus my thoughts upon the orb.\n\nI now understand why Zelig gave this crystal to me.\n\nTake my crystalline orb to the Forgotten Shore. Find the ruins of my old base on the upper reaches of the beach and place the orb in the center of town. Let the forgotten see the world through my heart and soul.", sourceObjective = "Orik Trueheart at Dawn's Reach in Dragonblight wants you to use Orik's Crystalline Orb in the ruins located at the Forgotten Shore to redeem the Forgotten.", progress = "Is it done?", completion = "<Orik beams a smile at you.>\n\nYou did a good thing this day, {name}. Hundreds of lost souls are now redeemed, thanks to you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12302] = { id = 12302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Words of Warning", description = "Thanks for helping me, {name}.  My name's Sasha.  Listen, I have to get the hell out of here.\n\nThe people that sent you here... my people... they've changed.  They're not good people anymore... and they want to turn you into one of... one of them.\n\nThis... 'test' they sent you on is just the beginning.\n\nHead to the northwestern end of Silverbrook.  You'll find something of interest to you.\n\nGood luck... and trust no one.", sourceObjective = "Go to the northwestern end of Silverbrook.", completion = "Who's there?  Are you here to kill me?\n\nPlease!  You don't have to do this!", sourceObjectiveStatus = "unverified-source-field" }
quests[12303] = { id = 12303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funding the War Effort", description = "<The quartermaster lowers his voice and whispers to you.>\n\n{class}, I need your help; our coffers are empty. The Kor'kron Vanguard at the Wrath Gate has taken all of our coin for the fight there.\n\nBut, I've heard whispers that there's treasure to be had amongst the wrecks on the Forgotten Shore to the southeast.\n\nWe have to do something soon, or we won't be able to continue the fight against the Scarlet Onslaught. War isn't cheap, you know!", sourceObjective = "Quartermaster Bartlett at Venomspite has asked you to recover 6 Forgotten Treasure.", progress = "How much of that Alliance treasure did you manage to get your hands on?", completion = "<The quartermaster gasps, but then his eyes narrow as he studies you for a moment.>\n\nI trust that you didn't stash any of this on the side for yourself? You wouldn't be that selfish when the fate of Venomspite is at stake?\n\nBesides, I'm going to reward you with a percentage of the take. It's not much, but in times like this, we all have to make sacrifices.", sourceObjectiveStatus = "unverified-source-field" }
quests[12304] = { id = 12304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beachfront Property", description = "It's time for Venomspite to expand!\n\nWe'll take care of the Onslaught in due time, but I want you to spearhead our efforts on the Forgotten Shore. The property value has outstanding potential and just look at that view!\n\nUnfortunately, there's an infestation of human ghosts, shipwrecked crews and the like who haven't quite realized that they're dead.\n\nClear the beach and the waters off the shore, and maybe you and I will talk about building a cozy, new mausoleum down there soon.", sourceObjective = "Surveyor Hansen, just north of the Forgotten Shore, has asked you to slay 20 Forgotten ghosts.", completion = "Can't you just see it now, {class}? It'll be the vacation spot of Northrend!\n\nWhat do you think of the name, \"Hansen's Cove\", or maybe \"{name} Bay\"? Kind of catchy, don't you think?", sourceObjectiveStatus = "unverified-source-field" }
quests[12305] = { id = 12305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parting Thoughts", description = "You have honored me and honored the memory of hundreds of Alliance veterans, {name}. Zelig was wise in sending you here. Please return to him and give him my thanks. He will be happy to hear of the events that transpired at the Forgotten Shore.\n\nI do not have the gift of foresight like Zelig, but I am certain that great things await you, friend.\n\nFarewell.", sourceObjective = "Return to Zelig the Visionary at Wintergarde Keep in Dragonblight.", completion = "<Zelig smiles.>\n\nIt is I who owe you a debt of gratitude, hero. Orik is like a brother to me. You have changed his life and given renewed hope to countless others.", sourceObjectiveStatus = "unverified-source-field" }
quests[12306] = { id = 12306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brew of the Month Club", description = "There is strength in numbers, {name}.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", sourceObjective = "Bring the \"Brew of the Month\" club membership form to Ray'ma in Orgrimmar.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, {name}?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like.", sourceObjectiveStatus = "unverified-source-field" }
quests[12307] = { id = 12307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wolfsbane Root", description = "Have you heard of the wolfsbane plant?  It is a horrible weed... it destroys our farmable crops.\n\nWe spent all of last week cutting them down, but the roots are beginning to sprout again.\n\nIt might not seem like an urgent matter, but a resurgence of the plant could be a real... disaster.  Do you think you could help us by uprooting them where you find them near the village?", sourceObjective = "Katja in Silverbrook wants you to uproot 8 Wolfsbane Roots.", progress = "Yes, {class}?", completion = "<Katja reels away from you nervously.>\n\nThank you, {name}.  You didn't get any wolfsbane on you, did you?  I've got these... allergies that act up once in a while.", sourceObjectiveStatus = "unverified-source-field" }
quests[12308] = { id = 12308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Escape from Silverbrook", description = "You... you're not one of them?  Quick!  Let me out!\n\nWe have to get to Amberpine Lodge immediately!  Once Lieutenant Dumont finds out who these people really are, this town will be reduced to rubble!", sourceObjective = "Open the Wooden Cage and help the Freed Alliance Scout escape from Silverbrook. Report to Lieutenant Dumont when you reach Amberpine Lodge.", completion = "Worgen.  Blasted, Light-forsaken, filth-ridden worgen.\n\nIt's time we showed the locals what us civilized folk do with beasts like them.", sourceObjectiveStatus = "unverified-source-field" }
quests[12309] = { id = 12309, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find Durkon!", description = "After the Scourge breached the south wall, I ordered Cavalier Durkon to investigate the town crypt. Moments ago I was handed his report.\n\nThe undead that plague us are coming from two sources: the ruins of Wintergarde, now a breeding ground for Scourge, and our very own town crypt! Amidst the chaos and confusion the Scourge managed to get a necrolord inside the crypt.\n\nIn his message, Durkon requested assistance. You will find him and help him, {name}. The crypt is on the western border of the town square.", sourceObjective = "Seek out Cavalier Durkon at the Wintergarde Crypt in Dragonblight.", completion = "Oh brother, it's a mess down there! I barely made it out last time - which is what prompted my request to the High Commander.\n\n<Durkon looks you up and down.>\n\nYou got that crazy look in your eyes, {race}. Thankfully, you're gonna need to be crazy to do what I'm about to ask of you.", sourceObjectiveStatus = "unverified-source-field" }
quests[12310] = { id = 12310, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Swift Response", description = "Our response must be immediate.  Decisive.  We must teach these savages not to cross us.\n\nOur scouts have located what's left of the Silverbrook trappers... you know, the ones you didn't get to douse in flames.  Apparently they're blockading the road to the southeast... perhaps they're trying to box us in.\n\nHead to the Forest's Edge post and take care of them.  Their leader's reported to be a man named Vladek... make sure he's dealt with.", sourceObjective = "Lieutenant Dumont wants you to go to Forest's Edge Post and slay Vladek and 7 Silverbrook Hunters.", completion = "It's a shame those trappers turned out to be... afflicted.  We sure could've used a few more fighting men.\n\nMay the poor souls rest in peace.", sourceObjectiveStatus = "unverified-source-field" }
quests[12311] = { id = 12311, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Noble's Crypt", description = "Held within the cold stone walls of this crypt are the remains of the nobles and dignitaries that died in Northrend. At its very core now sits a necrolord who raises the corpses as servants of the Scourge.\n\nYou must make your way to the bottom of the Wintergarde Crypt and kill Necrolord Amarion. Only then will the assault from within cease!\n\nAnd {name}, be on the lookout for any information that might be laying about inside the room where Amarion resides.", sourceObjective = "Cavalier Durkon at Wintergarde Keep wants you to slay Necrolord Amarion.", completion = "Now if we could stop the Scourge attacks coming from outside the keep we might be able to send help to Lord Fordragon at the Wrathgate.", sourceObjectiveStatus = "unverified-source-field" }
quests[12312] = { id = 12312, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Scourge", description = "Scrawled across the flesh-bound chapters of this tome are strange symbols and shapes that seem to have been scraped into the pages with a blade. You have no idea what is written, but you are certain that whatever it is, it must be important.\n\nDeliver the tome to Cavalier Durkon standing guard topside at Wintergarde Crypt.", sourceObjective = "Deliver the Flesh-bound Tome to Cavalier Durkon at Wintergarde Keep in Dragonblight.", progress = "A Scourge tome?", completion = "Whatever information is held in this book must be of great importance! I could hear the howls and wails echoing through the crypt as you made your escape!\n\nThe High Commander must be notified!", sourceObjectiveStatus = "unverified-source-field" }
quests[12314] = { id = 12314, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down With Captain Zorna!", description = "The Horde's forces are poised to break through our lines and complete their conquest of Venture Bay if we do not act. The Horde's forces in the port are commanded by Captain Zorna, near the ship on the far side of the bay.\n\nIf you can defeat her, the Horde's offensive will falter and we can seize the chance to capture the port. Beware, {name}, for Zorna is a fierce fighter. It may take several people to defeat her, or if you have access to a repaired shredder, you might try using it to your advantage.", sourceObjective = "Slay Captain Zorna and report to Baron Freeman at Venture Bay.", completion = "Well done, {name}! Without their leader, the Horde is weak and disorganized. I will order our men forward.", sourceObjectiveStatus = "unverified-source-field" }
quests[12315] = { id = 12315, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crush Captain Brightwater!", description = "With every advance, our men are met by fresh Alliance reinforcements. It's almost as though their commander anticipates my every move!\n\nThe time has come for good Captain Brightwater to meet his end. He commands his troops from aboard an Alliance destroyer at the far end of the bay.\n\nThis will be no easy fight, {name}. Take along a couple of trusted friends, or if you have a key to one of those repaired shredders, use it to disembowel Brightwater! Either way, he must fall!", sourceObjective = "Slay Captain Brightwater and report to General Khazgar at Venture Bay.", progress = "Have you eliminated the enemy captain?", completion = "You are a true soldier of the Horde, {name}. Your bravery will inspire my men to victory!", sourceObjectiveStatus = "unverified-source-field" }
quests[12316] = { id = 12316, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them at Bay!", description = "We cannot permit the Horde to control Venture Bay. The port is essential to our operations in Grizzly Hills and beyond.\n\nCaptain Stoutmantle has taken the rest of the Westfall Brigade east in search of a passage through the mountains, so we'll have no reinforcements.\n\nGo into the field, {name}, and kill the Conquest Hold berserkers the Horde has sent against us. Cut them down until none remain standing. The Alliance must have this port!", sourceObjective = "Defeat 10 Horde units or players in Venture Bay and return to Lieutenant Stuart.", completion = "Your bravery has inspired the men of the Westfall Brigade. Even now they fight with greater ferocity. The port will soon be ours.", sourceObjectiveStatus = "unverified-source-field" }
quests[12317] = { id = 12317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keep Them at Bay", description = "This wretched Westfall Brigade is proving a tougher opponent than we'd thought. Though few in number, they fight well and bravely, but we cannot afford to wait them out.\n\nConqueror Krenna's orders were to capture the port quickly. You must break the stalemate, {name}. Find the enemy's marines and slaughter them until the resistance ceases. Only then will we be able to claim ownership of the port.\n\nGo quickly. We don't want to keep Conqueror Krenna waiting.", sourceObjective = "Defeat 10 Alliance units or players in Venture Bay and return to Centurion Kaggrum.", progress = "Have you done as ordered?", completion = "The port will soon fall to us. You have done well this day, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12318] = { id = 12318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Save Brewfest!", description = "{name}, our spies have discovered a fiendish plot!  The Dark Iron dwarves want our beloved Brewfest destroyed!\n\nCoren Direbrew, head of a renegade family of brewers, has marshaled the dwarves of Blackrock Depths.  Their vile mole machines attack us constantly.\n\nOur spy is in the Grim Guzzler, a tavern in the bowels of Blackrock Depths.  He'll know more of Direbrew's plot.\n\nFind our spy.  Save Brewfest!", sourceObjective = "Speak with the Brewfest Spy in the Grim Guzzler of Blackrock Depths.", completion = "You're from the Brewfest camp? Glory day!  Brewfest may yet be saved.\n\n{name}, Coren Direbrew must be stopped!  We cannot let him sabotage our sacred holiday.  Our brews must flow!", sourceObjectiveStatus = "unverified-source-field" }
quests[12319] = { id = 12319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mystery of the Tome", description = "What can it be, {name}? That was certainly no ordinary curse that the blasted lich put on you!\n\n<Durkon flips through the grisly pages of the tome.>\n\nI don't even know if I'm looking at it the right way. We must find out what information is held within this tome!\n\n<Durkon hands the book back to you.>\n\nThe High Commander will know what to do. Take the flesh-bound tome to him and tell him exactly what happened here.", sourceObjective = "Take the Flesh-bound Tome to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight.", progress = "The necrolord is no more?", completion = "<Halford's eyes widen.>\n\nThe fates smile down upon us on this day, {name}. I know just the person to see about this tome.", sourceObjectiveStatus = "unverified-source-field" }
quests[12320] = { id = 12320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Understanding the Language of Death", description = "Take the book and follow the path leading up to the barracks. Once inside the barracks take the staircase down to the prison. At the prison you will find Inquisitor Hallard and our mayor, Godfrey. I believe Godfrey might be the missing piece of this puzzle and Hallard the man to put it all together.\n\nGo now!", sourceObjective = "Take the Flesh-bound Tome to Inquisitor Hallard at the Wintergarde Keep prison.", progress = "You come from high command, my son?", completion = "Perhaps, with proper motivation, Godfrey will tell us what he knows about the tome.\n\n<Hallard turns to Mayor Godfrey.>\n\nIsn't that right, mayor?", sourceObjectiveStatus = "unverified-source-field" }
quests[12321] = { id = 12321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Righteous Sermon", description = "Godfrey Goodard, once a righteous man and mayor of Wintergarde, is now an agent of the Scourge. His transformation from man to undying ghoul has taken place slowly, over time. He hears the call of the Lich King now and lives only to serve his master.\n\nBut as with all Scourge, Godfrey knows the language of death and with proper motivation, will tell us what we need to know about the tome.\n\nOnce you hear what you need to hear, return to the High Commander at the front lines. I'll clean up here as needed.", sourceObjective = "Wait for Inquisitor Hallard to finish his Righteous Sermon and return to High Commander Halford Wyrmbane at Wintergarde Keep in Dragonblight with the information you uncover.", completion = "We should have known about the damned mausoleum. This is preposterous! Duke August Foehammer and Ambo Cash will be dispatched to the front lines in preparation for our next assault.\n\nOnce you have cleared the mines I will send you to Foehammer so that we may begin our attack against the Scourge of Naxxramas!\n\nThe information you have garnered thus far will be sent to Lord Fordragon at the Wrathgate upon the wings of our most able gryphon!", sourceObjectiveStatus = "unverified-source-field" }
quests[12323] = { id = 12323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke 'Em Out", description = "There are still pockets of cowardly Venture Company men holed up in some of the buildings at the center of Venture Bay. I need every man I can spare out there fighting against the Horde, but we can't allow those Venture Company stragglers to camp out in those buildings, either.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; they probably bite.", sourceObjective = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Sergeant Downey.", progress = "Have you smoked out the last of the Venture Company guys yet?", completion = "Well done, soldier! Now the rest of the men can focus their efforts on the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[12324] = { id = 12324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Smoke 'Em Out", description = "Not only is this port infested with sniveling Alliance cowards, but to make matters worse, there are still Venture Company employees holed up in some of the buildings. They're not worth the time it takes to kill and I can't spare the warriors anyway.\n\nMaybe we can \"convince\" them to make for their ship. Take this smoke bomb and use it to smoke out the stragglers from their places in the bunkhouse, sawmill, or stables. Don't get too close, though; there's no telling what diseases they're carrying.", sourceObjective = "Use the Smoke Bomb to drive 20 Venture Company Stragglers from their buildings and then report to Stone Guard Ragetotem.", progress = "Have you smoked out the last of the Venture Company vermin yet?", completion = "The general will be pleased that you've dealt with the Venture Company problem. Now, the men can focus on beating back the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[12325] = { id = 12325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Hostile Territory", description = "You have done much to advance our efforts against the Scourge, {name}. In fact, the morale of all those who have come into contact with you soars! Such is your influence over the soldiers and citizenry of Wintergarde, ally.\n\nAnd because of you we are now prepared to go on the offensive! You are to report to Duke August Foehammer, across the Carrion Fields at Thorson's Post, east of here. Gryphon Commander Urik at the gryphon station has prepared a special gryphon to drop you behind enemy lines. Go now!", sourceObjective = "Speak with Gryphon Commander Urik to secure a ride to Thorson's Post. Report to Duke August Foehammer when you arrive at Thorson's Post in Dragonblight.", completion = "Ah, the distinguished hero arrives. Welcome to ground zero, {name}. Allow me to bring you up to speed!\n\nThel'zan's most powerful forces have made their way into the Wintergarde Mausoleum. They plumb its depths in search of corpses and souls to send against Wintergarde while Naxxramas rains down terrible Scourge plague machines, set to hold us at bay!\n\nWe must strike now and hope that Lord Fordragon is able to hold out at the Wrathgate for just a little longer.", sourceObjectiveStatus = "unverified-source-field" }
quests[12326] = { id = 12326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Steamtank Surprise", description = "This is a seek and destroy mission. You'll be driving a tank into the Carrion Fields to dismantle Scourge plague wagons. With the tank comes a crew of three 7th Legion soldiers. All must survive if this mission is to succeed!\n\nYou'll need to get in close to a plague wagon to unleash your engineer. Let them do their deed and move on to the next one. When the field is clear of plague wagons, head to the mausoleum in front of the ruined keep and drop off the rest of your crew. Meet with Ambo Cash inside.", sourceObjective = "Use an Alliance Steam Tank to destroy 6 Plague Wagons and deliver the 7th Legion Elites to Wintergarde Mausoleum. Speak with Ambo Cash inside the Wintergarde Mausoleum in Dragonblight should you succeed.", progress = "Name's Cash. Ambo Cash. And the pleasure is all yours.", completion = "Why I'm not wearing any pants isn't important. Let's just say I took some Scourge shrapnel in the wrong place and leave it at that, ok?\n\nSo you wiped out those plague wagons up in the fields and got my soldiers here in one piece. Impressive. You're one of the first to make it this far, friend. Too bad you gotta go right back out into the Carrion Fields. Yep, we've had a bit of a setback.", sourceObjectiveStatus = "unverified-source-field" }
quests[12327] = { id = 12327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Body Experience", description = "Ah, you seek a vision of the past.  You're a wise {race}.\n\nEvery time someone drops by for a reading, they seem to always ask about the future.  When you get to be my age, you learn that scrying the past, more often than not, is more useful.\n\nDrink this potion and peer into my crystal ball.  Let us see what knowledge we can obtain.", sourceObjective = "Drink the Gossamer Potion near Ruuna's Crystal Ball and witness the Vision from the Past.", progress = "Yes, {name}?", completion = "Did you learn anything from your vision?  You mentioned Solstice Village during your trance -- which marks the second time someone has spoken the place's name today.", sourceObjectiveStatus = "unverified-source-field" }
quests[12328] = { id = 12328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruuna's Request", description = "I will not charge you gold for my services, for I can foresee that your actions are necessary and much hinges on what you learn today.\n\nI will, however, ask you to collect a reagent for me.  Obtain gossamer dust from the fern feeder moths northeast of here.  Do this and I will prepare a potion that will take you to the time and place where the events took place that you need to witness.", sourceObjective = "Ruuna the Blind wants you to obtain 4 handfuls of Gossamer Dust.", progress = "Did you obtain the dust, {name}?", completion = "Good.  These will do just fine.\n\nI will have the potion ready for you in no time at all.", sourceObjectiveStatus = "unverified-source-field" }
quests[12329] = { id = 12329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate and Coincidence", description = "There are two types of people in this world, {name}.  Those who believe in coincidence and those who don't.\n\nOn the day I lost my eyesight I was given the gift of clairvoyance.  I suppose you can guess what sort of person I am.\n\nEarlier today, a young woman named Sasha was granted the same vision you were.  You will want to talk to her.\n\nYou'll find her directly east of here at the White Pine Trading Post, on the way to Solstice Village.", sourceObjective = "Speak to Sasha at the White Pine Trading Post.", completion = "I was wondering when you'd turn up.  Think you can give me a hand here?", sourceObjectiveStatus = "unverified-source-field" }
quests[12330] = { id = 12330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anatoly Will Talk", description = "My sister is here somewhere, and I can't seem to get this monster to talk.\n\nHe doesn't seem to care about his own well-being, but I've an idea.  I knew Anatoly's wife, Tatjana, from before the wolfcult arrived -- she was a horse-handler.\n\nTake this tranquillizer dart.  Bring her back alive, we're going to need her if we're to have any leverage with Anatoly.\n\nI will help you find the person behind all this once we save my sister.", sourceObjective = "Sasha at the White Pine Trading Post wants you to take the Tranquilizer Dart and use it on Tatjana in Solstice Village. Bring Tatjana back to the White Pine Trading Post.", progress = "I'm glad to see you in one piece.", completion = "That... that was close.\n\nWe need to save Anya.  Now!", sourceObjectiveStatus = "unverified-source-field" }
quests[12331] = { id = 12331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage mop-classic ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceFlavor = "mop-classic", sourceRevision = "ff01f8cbdd3bd8fd7644fb785dcf1e6f76a28c37", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", sourceObjective = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", sourceObjectiveStatus = "unverified-source-field" }
